import { TIPTAP_TABLE_CELL_TYPE, TIPTAP_TABLE_ROW_TYPE } from './../../ricos-content/index.js';
import { Node_Type } from './../../ricos-types/index.js';

export const getDefaultTable = (rowNum: $TSFixMe, colNum: $TSFixMe) => {
  return Array(rowNum)
    .fill(0)
    .map(_ => ({
      type: TIPTAP_TABLE_ROW_TYPE,
      content: Array(colNum)
        .fill(0)
        .map(_ => ({
          type: TIPTAP_TABLE_CELL_TYPE,
          content: [
            {
              type: Node_Type.PARAGRAPH,
              content: [],
            },
          ],
        })),
    }));
};
