import type { Fragment, Node as ProsemirrorNode, Schema } from './../../../tiptap/pm/model.js';

import { createCell } from './create-cell.js';
import { getTableNodeTypes } from './get-table-node-types.js';

export function createTable(
  schema: Schema,
  rowsCount: number,
  colsCount: number,
  withHeaderRow: boolean,
  cellContent?: Fragment | ProsemirrorNode
): ProsemirrorNode {
  const types: Record<string, any> = getTableNodeTypes(schema);
  const headerCells: ProsemirrorNode[] = [];
  const cells: ProsemirrorNode[] = [];

  // oxlint-disable-next-line fp/no-loops
  for (let index = 0; index < colsCount; index += 1) {
    const cell = createCell(types.cell, cellContent);

    if (cell) {
      cells.push(cell);
    }

    if (withHeaderRow) {
      const headerCell = createCell(types.header_cell, cellContent);

      if (headerCell) {
        headerCells.push(headerCell);
      }
    }
  }

  const rows: any[] = [];

  // oxlint-disable-next-line fp/no-loops
  for (let index = 0; index < rowsCount; index += 1) {
    rows.push(types.row.createChecked(null, withHeaderRow && index === 0 ? headerCells : cells));
  }

  return types.table.createChecked(null, rows);
}
