import {
  TIPTAP_TABLE_CELL_TYPE,
  TIPTAP_TABLE_HEADER_CELL_TYPE,
  TIPTAP_TABLE_TYPE,
} from './../../../ricos-content/consts.js';
import { resolveDocumentColorToCss } from './../../../_shared/theme-color-token.js';
import type { Node as ProseMirrorNode } from './../../../tiptap/pm/model.js';
import { Decoration, DecorationSet } from './../../../tiptap/pm/view.js';

import type { BorderStyle, CellBorders } from '../../borders/resolve-cell-borders.js';
import { getCornerOffset, resolveCellBordersPm } from '../../borders/resolve-cell-borders.js';
import { TableMap } from '../tablemap.js';

// Compute actual corner offsets for a border using shared getCornerOffset
const computeCornerOffsets = (
  border: BorderStyle,
  isHorizontal: boolean
): { startOffset: number; endOffset: number } => {
  if (!border) {
    return { startOffset: 0, endOffset: 0 };
  }

  const startOffset = getCornerOffset({
    thisZ: border.zIndex,
    perpZ: border.perpStartZ,
    parallelZ: border.parallelStartZ,
    extAmount: border.extendStart,
    isHorizontal,
    isStartCorner: true,
  });

  const endOffset = getCornerOffset({
    thisZ: border.zIndex,
    perpZ: border.perpEndZ,
    parallelZ: border.parallelEndZ,
    extAmount: border.extendEnd,
    isHorizontal,
    isStartCorner: false,
  });

  return { startOffset, endOffset };
};

export function borderStyleToCSS(borders: CellBorders): string {
  const vars: string[] = [];
  const resolveBorderColor = (color: string) => resolveDocumentColorToCss(color) ?? color;

  if (borders.top) {
    const { startOffset, endOffset } = computeCornerOffsets(borders.top, true);
    vars.push(`--bt-c:${resolveBorderColor(borders.top.color)}`);
    vars.push(`--bt-w:${borders.top.width}px`);
    vars.push(`--bt-es:${startOffset}px`);
    vars.push(`--bt-ee:${endOffset}px`);
    vars.push(`--bt-z:${borders.top.zIndex}`);
  }
  if (borders.bottom) {
    const { startOffset, endOffset } = computeCornerOffsets(borders.bottom, true);
    vars.push(`--bb-c:${resolveBorderColor(borders.bottom.color)}`);
    vars.push(`--bb-w:${borders.bottom.width}px`);
    vars.push(`--bb-es:${startOffset}px`);
    vars.push(`--bb-ee:${endOffset}px`);
    vars.push(`--bb-z:${borders.bottom.zIndex}`);
  }
  if (borders.left) {
    const { startOffset, endOffset } = computeCornerOffsets(borders.left, false);
    vars.push(`--bl-c:${resolveBorderColor(borders.left.color)}`);
    vars.push(`--bl-w:${borders.left.width}px`);
    vars.push(`--bl-es:${startOffset}px`);
    vars.push(`--bl-ee:${endOffset}px`);
    vars.push(`--bl-z:${borders.left.zIndex}`);
  }
  if (borders.right) {
    const { startOffset, endOffset } = computeCornerOffsets(borders.right, false);
    vars.push(`--br-c:${resolveBorderColor(borders.right.color)}`);
    vars.push(`--br-w:${borders.right.width}px`);
    vars.push(`--br-es:${startOffset}px`);
    vars.push(`--br-ee:${endOffset}px`);
    vars.push(`--br-z:${borders.right.zIndex}`);
  }

  return vars.join(';');
}

export const cellEdgeDecorations = (doc: ProseMirrorNode): DecorationSet => {
  const decorations: Decoration[] = [];

  doc.descendants((node, pos) => {
    if (node.type.name === TIPTAP_TABLE_TYPE) {
      const map = TableMap.get(node);
      const tableStart = pos + 1;
      const cellSpacing = (node.attrs.tableData?.cellSpacing as number | undefined) ?? 0;

      // Compute resolved borders for this table
      const resolvedBorders = resolveCellBordersPm(node, {
        drawDefaultGrid: true,
        cellSpacing,
      });

      // Create a map of cellPos -> cellId for lookup
      const cellIdByPos = new Map<number, string>();
      node.descendants((cellNode: ProseMirrorNode, cellPos: number) => {
        if (
          cellNode.type.name === TIPTAP_TABLE_CELL_TYPE ||
          cellNode.type.name === TIPTAP_TABLE_HEADER_CELL_TYPE
        ) {
          cellIdByPos.set(cellPos, cellNode.attrs.id);
        }
      });

      for (let i = 0; i < map.map.length; i++) {
        const cellPos = map.map[i];

        // Skip duplicate entries (cells with rowspan/colspan appear multiple times)
        if (i > 0 && map.map[i - 1] === cellPos) {
          continue;
        }

        const cellNode = node.nodeAt(cellPos);
        if (
          !cellNode ||
          (cellNode.type.name !== TIPTAP_TABLE_CELL_TYPE &&
            cellNode.type.name !== TIPTAP_TABLE_HEADER_CELL_TYPE)
        ) {
          continue;
        }

        const placement = map.findCell(cellPos);
        const cellId = cellNode.attrs.id;
        const borders = resolvedBorders.get(cellId);

        const attrs: Record<string, string> = {
          'data-visual-col': String(placement.col),
          'data-visual-row': String(placement.row),
        };

        // Add border CSS custom properties
        if (borders) {
          const borderStyle = borderStyleToCSS(borders);
          if (borderStyle) {
            attrs.style = borderStyle;
          }
        }

        const absoluteCellPos = tableStart + cellPos;
        decorations.push(
          Decoration.node(absoluteCellPos, absoluteCellPos + cellNode.nodeSize, attrs)
        );
      }
    }
  });

  return DecorationSet.create(doc, decorations);
};
