import type { Editor } from './../../../tiptap/core/index.js';
import { Plugin } from './../../../tiptap/pm/state.js';
import type { PluginKey } from './../../../tiptap/pm/state.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

import { preserveScrollDuring } from './preserve-scroll.js';
import { isSelectingCells } from './table-editing-plugin.js';

export interface ResizeDragHandlers<TArgs, TState> {
  pluginKey: PluginKey;
  setActive: (view: EditorView, active: boolean) => void;
  isOtherActive: (view: EditorView) => boolean;
  begin: (view: EditorView, args: TArgs & { event: PointerEvent }) => TState | null;
  applyFrame: (view: EditorView, event: MouseEvent, state: TState) => void;
  commit: (view: EditorView, state: TState) => void;
}

export interface ResizeDragController<TArgs> {
  plugin: Plugin;
  start: (view: EditorView, args: TArgs & { event: PointerEvent }) => boolean;
}

const resizeTicksByView = new WeakMap<EditorView, () => void>();

export const setResizeTick = (view: EditorView, cb: () => void): void => {
  resizeTicksByView.set(view, cb);
};

export const clearResizeTick = (view: EditorView, cb: () => void): void => {
  if (resizeTicksByView.get(view) === cb) {
    resizeTicksByView.delete(view);
  }
};

export const triggerResizeTick = (view: EditorView): void => {
  resizeTicksByView.get(view)?.();
};

export const createResizeDragController = <TArgs, TState>(
  editor: Editor,
  handlers: ResizeDragHandlers<TArgs, TState>
): ResizeDragController<TArgs> => {
  let activeDragState: TState | null = null;
  let capturedElement: HTMLElement | null = null;
  let capturedPointerId: number | null = null;
  let globalCleanup: (() => void) | null = null;
  let pendingDragRaf = 0;
  let pendingDragEvent: MouseEvent | null = null;

  const releasePointer = (): void => {
    if (capturedElement && capturedPointerId !== null) {
      try {
        capturedElement.releasePointerCapture(capturedPointerId);
      } catch {
        // Pointer capture may already be released.
      }
    }
    capturedElement = null;
    capturedPointerId = null;
  };

  const cancelPendingFrame = (): void => {
    if (pendingDragRaf !== 0) {
      cancelAnimationFrame(pendingDragRaf);
      pendingDragRaf = 0;
    }
    pendingDragEvent = null;
  };

  const flushPendingFrame = (view: EditorView, state: TState): void => {
    if (pendingDragRaf !== 0) {
      cancelAnimationFrame(pendingDragRaf);
      pendingDragRaf = 0;
    }
    const event = pendingDragEvent;
    pendingDragEvent = null;
    if (event) {
      handlers.applyFrame(view, event, state);
    }
  };

  const cleanupDrag = (view: EditorView): void => {
    releasePointer();
    if (globalCleanup) {
      globalCleanup();
    }
    handlers.setActive(view, false);
    activeDragState = null;
  };

  const finish = (view: EditorView): boolean => {
    const state = activeDragState;
    if (!state) {
      return false;
    }

    flushPendingFrame(view, state);
    cleanupDrag(view);
    preserveScrollDuring(view, () => handlers.commit(view, state));
    return true;
  };

  const start = (view: EditorView, args: TArgs & { event: PointerEvent }): boolean => {
    const { event } = args;
    if (event.button !== 0) {
      return false;
    }
    if (handlers.isOtherActive(view) || isSelectingCells(view.state) || !editor.isEditable) {
      return false;
    }

    const target = event.target as HTMLElement | null;
    if (target) {
      try {
        target.setPointerCapture(event.pointerId);
        capturedElement = target;
        capturedPointerId = event.pointerId;
      } catch {
        // Document-level fallback listeners still terminate the drag.
      }
    }

    const cleanupGlobalListeners = () => {
      document.removeEventListener('pointerup', handleGlobalPointerUp, true);
      document.removeEventListener('pointercancel', handleGlobalPointerUp, true);
      globalCleanup = null;
    };
    const handleGlobalPointerUp = (e: PointerEvent) => {
      if (e.pointerId !== event.pointerId) {
        return;
      }
      if (activeDragState) {
        finish(view);
      } else {
        cleanupGlobalListeners();
      }
    };

    document.addEventListener('pointerup', handleGlobalPointerUp, true);
    document.addEventListener('pointercancel', handleGlobalPointerUp, true);
    globalCleanup = cleanupGlobalListeners;

    const state = handlers.begin(view, args);
    if (state === null) {
      releasePointer();
      cleanupGlobalListeners();
      return false;
    }

    activeDragState = state;
    handlers.setActive(view, true);
    event.preventDefault();
    event.stopPropagation();
    return true;
  };

  const guardEvent = (view: EditorView): boolean =>
    activeDragState !== null && !handlers.isOtherActive(view) && editor.isEditable;

  const plugin = new Plugin({
    key: handlers.pluginKey,
    props: {
      handleDOMEvents: {
        pointermove: (view, event) => {
          if (!guardEvent(view)) {
            return false;
          }
          pendingDragEvent = event;
          if (pendingDragRaf === 0) {
            const drag = activeDragState;
            pendingDragRaf = requestAnimationFrame(() => {
              pendingDragRaf = 0;
              const e = pendingDragEvent;
              pendingDragEvent = null;
              if (e && activeDragState === drag && drag !== null) {
                handlers.applyFrame(view, e, drag);
              }
            });
          }
          event.preventDefault();
          event.stopPropagation();
          return true;
        },
        pointerup: view => (guardEvent(view) ? finish(view) : false),
        pointercancel: view => (guardEvent(view) ? finish(view) : false),
      },
    },
    view(view) {
      return {
        destroy() {
          cancelPendingFrame();
          releasePointer();
          if (globalCleanup) {
            globalCleanup();
          }
          if (activeDragState) {
            handlers.setActive(view, false);
            activeDragState = null;
          }
        },
      };
    },
  });

  return { plugin, start };
};
