import type { EditorState, NodeSelection } from 'prosemirror-state';

import type { Node, NodeType, ResolvedPos, Schema } from './../../../tiptap/pm/model.js';

import { RicosCellSelection } from '../plugins/cellselection.js';
import { TableMap } from '../tablemap.js';
import type { Rect, TableRect, TableRole } from './types.js';

export function isEmpty(cell: Node): boolean {
  const c = cell.content;

  return c.childCount === 1 && c.child(0).isTextblock && c.child(0).childCount === 0;
}

export function cellsOverlapRectangle({ width, height, map }: TableMap, rect: Rect) {
  let indexTop = rect.top * width + rect.left,
    indexLeft = indexTop;
  let indexBottom = (rect.bottom - 1) * width + rect.left,
    indexRight = indexTop + (rect.right - rect.left - 1);
  for (let i = rect.top; i < rect.bottom; i++) {
    if (
      (rect.left > 0 && map[indexLeft] === map[indexLeft - 1]) ||
      (rect.right < width && map[indexRight] === map[indexRight + 1])
    ) {
      return true;
    }
    indexLeft += width;
    indexRight += width;
  }
  for (let i = rect.left; i < rect.right; i++) {
    if (
      (rect.top > 0 && map[indexTop] === map[indexTop - width]) ||
      (rect.bottom < height && map[indexBottom] === map[indexBottom + width])
    ) {
      return true;
    }
    indexTop++;
    indexBottom++;
  }
  return false;
}

/**
 * @public
 */
export function cellAround($pos: ResolvedPos): ResolvedPos | null {
  for (let d = $pos.depth - 1; d > 0; d--) {
    if ($pos.node(d).type.spec.tableRole === 'row') {
      return $pos.node(0).resolve($pos.before(d + 1));
    }
  }
  return null;
}

export function cellWrapping($pos: ResolvedPos): null | Node {
  for (let d = $pos.depth; d > 0; d--) {
    // Sometimes the cell can be in the same depth.
    const role = $pos.node(d).type.spec.tableRole;
    if (role === 'cell' || role === 'header_cell') {
      return $pos.node(d);
    }
  }
  return null;
}

/**
 * @public
 */
export function cellNear($pos: ResolvedPos): ResolvedPos | undefined {
  for (let after = $pos.nodeAfter, pos = $pos.pos; after; after = after.firstChild, pos++) {
    const role = after.type.spec.tableRole;
    if (role === 'cell' || role === 'header_cell') {
      return $pos.doc.resolve(pos);
    }
  }
  for (let before = $pos.nodeBefore, pos = $pos.pos; before; before = before.lastChild, pos--) {
    const role = before.type.spec.tableRole;
    if (role === 'cell' || role === 'header_cell') {
      return $pos.doc.resolve(pos - before.nodeSize);
    }
  }
}

/**
 * @public
 */
export function nextCell(
  $pos: ResolvedPos,
  axis: 'horiz' | 'vert',
  dir: number
): ResolvedPos | null {
  const table = $pos.node(-1);
  const map = TableMap.get(table);
  const tableStart = $pos.start(-1);

  const moved = map.nextCell($pos.pos - tableStart, axis, dir);
  return moved === null ? null : $pos.node(0).resolve(tableStart + moved);
}

/**
 * @public
 */
export function isInTable(state: EditorState): boolean {
  const $head = state.selection.$head;
  for (let d = $head.depth; d > 0; d--) {
    if ($head.node(d).type.spec.tableRole === 'row') {
      return true;
    }
  }
  return false;
}

/**
 * @internal
 */
export function selectionCell(state: EditorState): ResolvedPos {
  const sel = state.selection as RicosCellSelection | NodeSelection;
  if ('$anchorCell' in sel && sel.$anchorCell) {
    return sel.$anchorCell.pos > sel.$headCell.pos ? sel.$anchorCell : sel.$headCell;
  } else if ('node' in sel && sel.node && sel.node.type.spec.tableRole === 'cell') {
    return sel.$anchor;
  }
  const $cell = cellAround(sel.$head) || cellNear(sel.$head);
  if ($cell) {
    return $cell;
  }
  throw new RangeError(`No cell found around position ${sel.head}`);
}

/**
 * Helper to get the selected rectangle in a table, if any. Adds table
 * map, table node, and table start offset to the object for
 * convenience.
 *
 * @public
 */
export function selectedRect(state: EditorState): TableRect {
  const sel = state.selection;
  const $pos = selectionCell(state);
  const table = $pos.node(-1);
  const tableStart = $pos.start(-1);
  const map = TableMap.get(table);
  if (sel instanceof RicosCellSelection) {
    const rect = map.rectBetween(sel.$anchorCell.pos - tableStart, sel.$headCell.pos - tableStart);
    return { ...rect, tableStart, map, table };
  }
  const { col, row, colspan, rowspan } = map.findCell($pos.pos - tableStart);
  return {
    left: col,
    top: row,
    right: col + colspan,
    bottom: row + rowspan,
    tableStart,
    map,
    table,
  };
}

/**
 * @public
 */
export function tableNodeTypes(schema: Schema): Record<TableRole, NodeType> {
  let result = schema.cached.tableNodeTypes;
  if (!result) {
    result = schema.cached.tableNodeTypes = {};
    for (const name in schema.nodes) {
      if (Object.prototype.hasOwnProperty.call(schema.nodes, name)) {
        const type = schema.nodes[name],
          role = type.spec.tableRole;
        if (role) {
          result[role] = type;
        }
      }
    }
  }
  return result;
}

/**
 * @public
 */
export function columnIsHeader(map: TableMap, table: Node, col: number): boolean {
  const headerCell = tableNodeTypes(table.type.schema).header_cell;
  for (let row = 0; row < map.height; row++) {
    if (table.nodeAt(map.map[col + row * map.width])!.type !== headerCell) {
      return false;
    }
  }
  return true;
}

export function rowIsHeader(map: TableMap, table: Node, row: number): boolean {
  const headerCell = tableNodeTypes(table.type.schema).header_cell;
  for (let col = 0; col < map.width; col++) {
    if (table.nodeAt(map.map[col + row * map.width])?.type !== headerCell) {
      return false;
    }
  }
  return true;
}

export function isHeaderEnabledByType(
  type: 'row' | 'column',
  rect: TableRect,
  types: Record<string, NodeType>
): { enabled: boolean; spansCrossBoundary: boolean } {
  // Get cell positions for first row or first column
  const cellPositions = rect.map.cellsInRect({
    left: 0,
    top: 0,
    right: type === 'row' ? rect.map.width : 1,
    bottom: type === 'column' ? rect.map.height : 1,
  });

  let enabled = true;
  let spansCrossBoundary = false;
  for (let i = 0; i < cellPositions.length; i++) {
    const cell = rect.table.nodeAt(cellPositions[i]);
    if (!cell) {
      continue;
    }
    if (cell.type !== types.header_cell) {
      enabled = false;
    }
    // A rowspan > 1 in row 0 or colspan > 1 in col 0 crosses the header boundary
    if (type === 'row' ? cell.attrs.rowspan > 1 : cell.attrs.colspan > 1) {
      spansCrossBoundary = true;
    }
  }

  return { enabled, spansCrossBoundary };
}

export function getTableRectFromDoc(doc: Node, tableStart: number): TableRect {
  const $pos = doc.resolve(tableStart + 1);
  const table = $pos.node(-1);
  const actualTableStart = $pos.start(-1);
  const map = TableMap.get(table);
  return {
    left: 0,
    right: map.width,
    top: 0,
    bottom: map.height,
    table,
    tableStart: actualTableStart,
    map,
  };
}
