// ---------------------------------------------------------------------------
// Add column/row with borders + re-select
// ---------------------------------------------------------------------------

export const addColumnBeforeWithBorders =
  () =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const table = TableQuery.of(state.selection);
    if (!table) {
      return false;
    }
    const colRange = table.getSelectionColRange();
    if (!dispatch) {
      return true;
    }
    const rect = selectedRect(state);
    const tr = addColumn(state.tr, rect, rect.left, rect.left);
    const tableInfo = findTable(tr.selection);
    if (tableInfo) {
      canonicalizeBorders(tr, tableInfo.node, tableInfo.start);
    }
    if (colRange) {
      const newRect = getTableRectFromDoc(tr.doc, rect.tableStart);
      selectColumn(tr, newRect, colRange.first);
    }
    dispatch(tr);
    return true;
  };

