/* oxlint-disable fp/no-loops */
// This file defines a ProseMirror selection subclass that models
// table cell selections. The table plugin needs to be active to wire
// in the user interaction part of table selections (so that you
// actually get such selections when you select across cells).

import type { Node as ProseMirrorNode, ResolvedPos } from './../../../tiptap/pm/model.js';
import { Fragment, Slice } from './../../../tiptap/pm/model.js';
import { NodeSelection, Selection, SelectionRange, TextSelection } from './../../../tiptap/pm/state.js';
import type { Mappable } from './../../../tiptap/pm/transform.js';
import { Decoration, DecorationSet } from './../../../tiptap/pm/view.js';

import { DATA_CELL_SELECTED } from '../../data-hooks.js';
import type { Rect } from '../tablemap.js';
import { TableMap } from '../tablemap.js';
import styles from './table-scss.js';

export function drawCellSelection(state: $TSFixMe) {
  const selection = state.selection;

  if (!selection.$headCell && !(selection instanceof RicosCellSelection)) {
    return null;
  }

  const cells: Decoration[] = [];

  // Determine if single cell selection
  let isSingleCellSelection = false;
  if (selection instanceof RicosCellSelection) {
    isSingleCellSelection = selection.isSingleCell();
  } else if (selection.$anchorCell && selection.$headCell) {
    isSingleCellSelection = selection.$anchorCell.pos === selection.$headCell.pos;
  }

  selection.forEachCell((node: $TSFixMe, pos: $TSFixMe) => {
    cells.push(
      Decoration.node(pos, pos + node.nodeSize, {
        class: isSingleCellSelection ? styles.selectedCell : styles.selectedCells,
        [DATA_CELL_SELECTED]: 'true',
      })
    );
  });

  return DecorationSet.create(state.doc, cells);
}

function isCellBoundarySelection({ $from, $to }: $TSFixMe) {
  if ($from.pos === $to.pos || $from.pos < $from.pos - 6) {
    return false;
  } // Cheap elimination
  let afterFrom = $from.pos,
    beforeTo = $to.pos,
    depth = $from.depth;
  for (; depth >= 0; depth--, afterFrom++) {
    if ($from.after(depth + 1) < $from.end(depth)) {
      break;
    }
  }
  for (let d = $to.depth; d >= 0; d--, beforeTo--) {
    if ($to.before(d + 1) > $to.start(d)) {
      break;
    }
  }
  return afterFrom === beforeTo && /row|table/.test($from.node(depth).type.spec.tableRole);
}

function isTextSelectionAcrossCells({ $from, $to }: $TSFixMe) {
  let fromCellBoundaryNode;
  let toCellBoundaryNode;

  for (let i = $from.depth; i > 0; i--) {
    const node = $from.node(i);
    if (node.type.spec.tableRole === 'cell' || node.type.spec.tableRole === 'header_cell') {
      fromCellBoundaryNode = node;
      break;
    }
  }

  for (let i = $to.depth; i > 0; i--) {
    const node = $to.node(i);
    if (node.type.spec.tableRole === 'cell' || node.type.spec.tableRole === 'header_cell') {
      toCellBoundaryNode = node;
      break;
    }
  }

  return fromCellBoundaryNode !== toCellBoundaryNode && $to.parentOffset === 0;
}

export function normalizeSelection(state: $TSFixMe, tr: $TSFixMe, allowTableNodeSelection = false) {
  const sel = (tr || state).selection;
  const doc = (tr || state).doc;
  let normalize, role;
  if (sel instanceof NodeSelection && (role = sel.node.type.spec.tableRole)) {
    if (role === 'cell' || role === 'header_cell') {
      normalize = RicosCellSelection.create(doc, sel.from);
    } else if (role === 'row') {
      const $cell = doc.resolve(sel.from + 1);
      const table = $cell.node(-1);
      const tableStart = $cell.start(-1);
      const map = TableMap.get(table);
      const rect = { left: 0, right: map.width, top: $cell.index(-1), bottom: $cell.index(-1) + 1 };
      const cellPositions = map.cellsInRect(rect);
      const cells = cellPositions.map(pos => doc.resolve(tableStart + pos));
      normalize = new RicosCellSelection(cells, doc);
    } else if (!allowTableNodeSelection) {
      const map = TableMap.get(sel.node);
      const start = sel.from + 1;
      const firstCell = doc.resolve(start + 1);
      const tableStart = firstCell.start(-1);
      const rect = { left: 0, right: map.width, top: 0, bottom: map.height };
      const cellPositions = map.cellsInRect(rect);
      const cells = cellPositions.map(pos => doc.resolve(tableStart + pos));
      normalize = new RicosCellSelection(cells, doc);
    }
  } else if (sel instanceof TextSelection && isCellBoundarySelection(sel)) {
    normalize = TextSelection.create(doc, sel.from);
  } else if (sel instanceof TextSelection && isTextSelectionAcrossCells(sel)) {
    normalize = TextSelection.create(doc, sel.$from.start(), sel.$from.end());
  }
  if (normalize) {
    // oxlint-disable-next-line no-param-reassign
    (tr || (tr = state.tr)).setSelection(normalize);
  }
  return tr;
}

/**
 * Helper function to check if a resolved position points at a cell
 */
function pointsAtCell($pos: ResolvedPos): boolean {
  return (
    $pos.parent.type.spec.tableRole === 'row' &&
    ($pos.nodeAfter?.type.spec.tableRole === 'cell' ||
      $pos.nodeAfter?.type.spec.tableRole === 'header_cell')
  );
}

/**
 * Helper function to check if two cells are in the same table
 */
export function inSameTable($a: ResolvedPos, $b: ResolvedPos): boolean {
  return $a.depth === $b.depth && $a.pos >= $b.start(-1) && $a.pos <= $b.end(-1);
}

/**
 * A selection that supports multiple non-contiguous table cells.
 * Extends the standard Selection to allow selecting individual cells
 * that are not necessarily in a rectangular region.
 */
export class RicosCellSelection extends Selection {
  // Store absolute cell positions (relative to table start)
  public cellPositions: Set<number>;

  // Keep anchor and head for compatibility with existing code
  public $anchorCell: ResolvedPos;

  public $headCell: ResolvedPos;

  constructor(cells: ResolvedPos[], doc?: ProseMirrorNode) {
    if (cells.length === 0) {
      throw new Error('RicosCellSelection requires at least one cell');
    }

    const table = cells[0].node(-1);
    const tableStart = cells[0].start(-1);
    const resolvedDoc = doc || cells[0].node(0);

    // Create a SelectionRange for each cell
    const ranges = cells.map(cellPos => {
      const pos = cellPos.pos - tableStart;
      const cell = table.nodeAt(pos);

      if (!cell) {
        throw RangeError(`No cell with offset ${pos} found`);
      }

      const from = tableStart + pos + 1;
      return new SelectionRange(
        resolvedDoc.resolve(from),
        resolvedDoc.resolve(from + cell.content.size)
      );
    });

    super(ranges[0].$from, ranges[0].$to, ranges);

    this.cellPositions = new Set(cells.map(cellPos => cellPos.pos));
    this.$anchorCell = cells[0];
    this.$headCell = cells[cells.length - 1];
  }

  public map(doc: ProseMirrorNode, mapping: Mappable): RicosCellSelection | Selection {
    const mappedCells: ResolvedPos[] = [];

    for (const pos of this.cellPositions) {
      const mappedPos = mapping.map(pos);
      const $pos = doc.resolve(mappedPos);

      if (pointsAtCell($pos)) {
        mappedCells.push($pos);
      }
    }

    // If we lost some cells or they're not valid anymore, fall back to text selection
    if (mappedCells.length === 0) {
      const $anchor = doc.resolve(mapping.map(this.$anchorCell.pos));
      return TextSelection.between($anchor, $anchor);
    }

    // Verify all cells are in the same table
    const firstCell = mappedCells[0];
    const allInSameTable = mappedCells.every(cell => inSameTable(firstCell, cell));

    if (!allInSameTable) {
      return TextSelection.between(firstCell, firstCell);
    }

    return new RicosCellSelection(mappedCells, doc);
  }

  public content(): Slice {
    const table = this.$anchorCell.node(-1);
    const map = TableMap.get(table);
    const rect = this.getRect();
    const rows: ProseMirrorNode[] = [];

    for (let row = rect.top; row < rect.bottom; row++) {
      const rowContent: ProseMirrorNode[] = [];
      const rowNode = table.child(row);

      for (let col = rect.left; col < rect.right; col++) {
        const relativePos = map.map[row * map.width + col];
        const placement = map.findCell(relativePos);

        // Only add the cell if we are at its top-left corner (to handle spans)
        if (placement.row === row && placement.col === col) {
          const cell = table.nodeAt(relativePos);
          if (cell) {
            rowContent.push(cell);
          }
        }
      }
      rows.push(rowNode.type.create(rowNode.attrs, Fragment.from(rowContent)));
    }

    const newTable = table.type.create(table.attrs, Fragment.from(rows));
    return new Slice(Fragment.from(newTable), 1, 1);
  }

  public replace(tr: $TSFixMe, content: Slice = Slice.empty): void {
    // Check if all cells in the table are selected
    // If so and content is empty, delete the entire table (for cut operations)
    if (content === Slice.empty || content.size === 0) {
      const table = this.$anchorCell.node(-1);
      const tableStart = this.$anchorCell.start(-1);
      const map = TableMap.get(table);
      const totalCells = map.cellsInRect({
        left: 0,
        right: map.width,
        top: 0,
        bottom: map.height,
      }).length;

      if (this.cellPositions.size === totalCells) {
        const tablePos = tableStart - 1;
        tr.delete(tablePos, tablePos + table.nodeSize);
        const sel = Selection.findFrom(tr.doc.resolve(tablePos), 1);
        if (sel) {
          tr.setSelection(sel);
        }
        return;
      }
    }

    const mapFrom = tr.steps.length;
    const ranges = this.ranges;

    for (let i = 0; i < ranges.length; i++) {
      const { $from, $to } = ranges[i];
      const mapping = tr.mapping.slice(mapFrom);
      tr.replace(mapping.map($from.pos), mapping.map($to.pos), i ? Slice.empty : content);
    }

    const sel = Selection.findFrom(tr.doc.resolve(tr.mapping.slice(mapFrom).map(this.to)), -1);
    if (sel) {
      tr.setSelection(sel);
    }
  }

  public replaceWith(tr: $TSFixMe, node: ProseMirrorNode): void {
    this.replace(tr, new Slice(Fragment.from(node), 0, 0));
  }

  public forEachCell(f: (node: ProseMirrorNode, pos: number) => void): void {
    const table = this.$anchorCell.node(-1);
    const tableStart = this.$anchorCell.start(-1);

    for (const cellPos of this.cellPositions) {
      const relativePos = cellPos - tableStart;
      const cell = table.nodeAt(relativePos);
      if (cell) {
        f(cell, cellPos);
      }
    }
  }

  public eq(other: unknown): boolean {
    if (!(other instanceof RicosCellSelection)) {
      return false;
    }

    if (this.cellPositions.size !== other.cellPositions.size) {
      return false;
    }

    for (const pos of this.cellPositions) {
      if (!other.cellPositions.has(pos)) {
        return false;
      }
    }

    return true;
  }

  public toJSON() {
    const positions = Array.from(this.cellPositions).sort((a, b) => a - b);
    return {
      type: 'cell',
      anchor: positions[0],
      head: positions[positions.length - 1],
    };
  }

  public get jsonID(): string {
    return 'cell';
  }

  private getSelectionIndexes(): {
    map: TableMap;
    tableStart: number;
    selectedRowIndexes: Set<number>;
    selectedColumnIndexes: Set<number>;
  } {
    const table: ProseMirrorNode = this.$anchorCell.node(-1);
    const map: TableMap = TableMap.get(table);
    const tableStart: number = this.$anchorCell.start(-1);
    const selectedRowIndexes: Set<number> = new Set<number>();
    const selectedColumnIndexes: Set<number> = new Set<number>();

    for (const cellPos of this.cellPositions) {
      const relativePos: number = cellPos - tableStart;
      const placement = map.findCell(relativePos);
      for (
        let rowIndex = placement.row;
        rowIndex < placement.row + placement.rowspan;
        rowIndex += 1
      ) {
        selectedRowIndexes.add(rowIndex);
      }
      for (
        let columnIndex = placement.col;
        columnIndex < placement.col + placement.colspan;
        columnIndex += 1
      ) {
        selectedColumnIndexes.add(columnIndex);
      }
    }

    return {
      map,
      tableStart,
      selectedRowIndexes,
      selectedColumnIndexes,
    };
  }

  public isColSelection(): boolean {
    const { map, tableStart, selectedColumnIndexes } = this.getSelectionIndexes();
    const selectedCellPositions: Set<number> = this.cellPositions;

    if (selectedColumnIndexes.size === 0) {
      return false;
    }

    for (const columnIndex of selectedColumnIndexes) {
      const columnCells: number[] = map.cellsInRect({
        left: columnIndex,
        right: columnIndex + 1,
        top: 0,
        bottom: map.height,
      });
      const isColumnComplete: boolean = columnCells.every((cellPos: number) => {
        return selectedCellPositions.has(tableStart + cellPos);
      });
      if (!isColumnComplete) {
        return false;
      }
    }

    return true;
  }

  public isRowSelection(): boolean {
    const { map, tableStart, selectedRowIndexes } = this.getSelectionIndexes();
    const selectedCellPositions: Set<number> = this.cellPositions;

    if (selectedRowIndexes.size === 0) {
      return false;
    }

    for (const rowIndex of selectedRowIndexes) {
      const rowCells: number[] = map.cellsInRect({
        left: 0,
        right: map.width,
        top: rowIndex,
        bottom: rowIndex + 1,
      });
      const isRowComplete: boolean = rowCells.every((cellPos: number) => {
        return selectedCellPositions.has(tableStart + cellPos);
      });
      if (!isRowComplete) {
        return false;
      }
    }

    return true;
  }

  public isTableSelection(): boolean {
    const { map, tableStart } = this.getSelectionIndexes();
    const selectedCellPositions: Set<number> = this.cellPositions;
    const tableCells: number[] = map.cellsInRect({
      left: 0,
      right: map.width,
      top: 0,
      bottom: map.height,
    });

    return tableCells.every((cellPos: number) => {
      return selectedCellPositions.has(tableStart + cellPos);
    });
  }

  public getRect(): Rect {
    const cells: ResolvedPos[] = [];
    const doc = this.$anchorCell.node(0);
    for (const cellPos of this.cellPositions) {
      cells.push(doc.resolve(cellPos));
    }
    return getRectBetweenCells(cells);
  }

  static create(doc: ProseMirrorNode, ...cellPositions: number[]): RicosCellSelection {
    if (cellPositions.length === 0) {
      throw new Error('At least one cell position is required');
    }

    const cells = cellPositions.map(pos => {
      const $pos = doc.resolve(pos);
      if (!pointsAtCell($pos)) {
        throw new Error(`Position ${pos} does not point at a cell`);
      }
      return $pos;
    });

    return new RicosCellSelection(cells, doc);
  }

  // Toggle a cell in/out of the selection
  static toggleCell(
    currentSelection: Selection,
    cellPos: number,
    doc: ProseMirrorNode
  ): RicosCellSelection {
    const $cell = doc.resolve(cellPos);

    if (!pointsAtCell($cell)) {
      throw new Error(`Position ${cellPos} does not point at a cell`);
    }

    if (currentSelection instanceof RicosCellSelection) {
      const newPositions = new Set(currentSelection.cellPositions);

      if (newPositions.has(cellPos)) {
        // Remove cell if already selected
        newPositions.delete(cellPos);
        // Need at least one cell
        if (newPositions.size === 0) {
          return new RicosCellSelection([$cell], doc);
        }
      } else {
        // Add cell to selection
        newPositions.add(cellPos);
      }

      const cells = Array.from(newPositions).map(pos => doc.resolve(pos));
      return new RicosCellSelection(cells, doc);
    }

    // Not a cell selection yet, create new one
    return new RicosCellSelection([$cell], doc);
  }

  // Get count of selected cells
  public getCellCount(): number {
    return this.cellPositions.size;
  }

  // Check if this is a single cell selection
  public isSingleCell(): boolean {
    return this.cellPositions.size === 1;
  }
}

// Prevent native browser selection from showing
RicosCellSelection.prototype.visible = false;

/**
 * Calculate the bounding rectangle that encompasses all given cells,
 * accounting for rowspan and colspan.
 */
export const getRectBetweenCells = (cells: ResolvedPos[]): Rect => {
  if (cells.length === 0) {
    throw new Error('getRectBetweenCells requires at least one cell');
  }

  // Get the table and table map from the first cell
  const table = cells[0].node(-1);
  const tableStart = cells[0].start(-1);
  const map = TableMap.get(table);

  // --- 1. Compute initial bounds (union of all cells) -----
  let bounds: Rect | null = null;

  for (const cell of cells) {
    const relativePos = cell.pos - tableStart;
    const p = map.findCell(relativePos);

    if (!bounds) {
      bounds = { top: p.row, left: p.col, bottom: p.row + p.rowspan, right: p.col + p.colspan };
    } else {
      bounds.top = Math.min(bounds.top, p.row);
      bounds.left = Math.min(bounds.left, p.col);
      bounds.bottom = Math.max(bounds.bottom, p.row + p.rowspan);
      bounds.right = Math.max(bounds.right, p.col + p.colspan);
    }
  }

  if (!bounds) {
    throw new Error('Failed to compute bounds');
  }

  // --- 2. Track which cells we've processed ----------------
  const visited = new Set<number>();
  const queue: number[] = [];

  // --- 3. Seed queue with all cells inside initial bounds --
  for (let r = bounds.top; r < bounds.bottom; r++) {
    for (let c = bounds.left; c < bounds.right; c++) {
      const pos = map.map[r * map.width + c];
      if (!visited.has(pos)) {
        visited.add(pos);
        queue.push(pos);
      }
    }
  }

  // --- 4. Expand region using queue frontier ---------------
  // This handles cells with rowspan/colspan that extend beyond initial bounds
  while (queue.length) {
    const pos = queue.shift()!;
    const p = map.findCell(pos);

    // Expand bounds if this cell extends selection
    const newTop = Math.min(bounds.top, p.row);
    const newLeft = Math.min(bounds.left, p.col);
    const newBottom = Math.max(bounds.bottom, p.row + p.rowspan);
    const newRight = Math.max(bounds.right, p.col + p.colspan);

    const expanded =
      newTop < bounds.top ||
      newLeft < bounds.left ||
      newBottom > bounds.bottom ||
      newRight > bounds.right;

    if (!expanded) {
      continue;
    }

    bounds = { top: newTop, left: newLeft, bottom: newBottom, right: newRight };

    for (let r = bounds.top; r < bounds.bottom; r++) {
      for (let c = bounds.left; c < bounds.right; c++) {
        const p = map.map[r * map.width + c];
        if (!visited.has(p)) {
          visited.add(p);
          queue.push(p);
        }
      }
    }

    const isFullTable =
      bounds.top === 0 &&
      bounds.left === 0 &&
      bounds.bottom === map.height &&
      bounds.right === map.width;

    if (isFullTable) {
      return bounds;
    }
  }

  return bounds;
};

export const getCellsInExpandedRect = (
  doc: ProseMirrorNode,
  tableStart: number,
  map: TableMap,
  initialRect: Rect
): ResolvedPos[] => {
  const initialCellPositions = map.cellsOverlappingRect(initialRect);
  const initialCells = initialCellPositions.map(pos => doc.resolve(tableStart + pos));

  const expandedRect = getRectBetweenCells(initialCells);

  const cellPositions = map.cellsOverlappingRect(expandedRect);
  return cellPositions.map(pos => doc.resolve(tableStart + pos));
};
