import type { Editor } from './../../../tiptap/core/index.js';
import type { ResolvedPos } from './../../../tiptap/pm/model.js';
import type { EditorState, Transaction } from './../../../tiptap/pm/state.js';
import { Plugin, PluginKey, TextSelection } from './../../../tiptap/pm/state.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

import { fixTables } from '../commands/fix.js';
import { TableMap } from '../tablemap.js';
import { findTable } from '../utilities/find-table.js';
import { isRicosCellSelection } from '../utilities/is-selection-type.js';
import { RicosCellSelection, drawCellSelection, normalizeSelection } from './cellselection.js';
import { handleMouseDown, handlePaste } from './input.js';

// Export the key so it can be used to check if cell selection is in progress
export const selectingCellsKey = new PluginKey<number | null>('selectingCells');

export const isSelectingCells = (state: EditorState) => {
  return !!(
    selectingCellsKey.getState(state) !== null && selectingCellsKey.getState(state) !== undefined
  );
};

// :: () → Plugin
//
// Creates a [plugin](http://prosemirror.net/docs/ref/#state.Plugin)
// that, when added to an editor, enables cell-selection, handles
// cell-based copy/paste, and makes sure tables stay well-formed (each
// row has the same width, and cells don't overlap).
//
// You should probably put this plugin near the end of your array of
// plugins, since it handles mouse and arrow key events in tables
// rather broadly, and other plugins, like the gap cursor or the
// column-width dragging plugin, might want to get a turn first to
// perform more specific behavior.
export const tableEditingPlugin = ({
  editor,
  isMobile,
}: {
  editor: Editor;
  isMobile?: boolean;
}) => {
  const key = selectingCellsKey;
  return new Plugin({
    key,

    // This piece of state is used to remember when a mouse-drag
    // cell-selection is happening, so that it can continue even as
    // transactions (which might move its anchor cell) come in.
    state: {
      init() {
        return null;
      },
      apply(tr: Transaction, cur: number | null) {
        const set = tr.getMeta(key);
        if (set !== null && set !== undefined) {
          return set === -1 ? null : set;
        }
        if (cur === null || !tr.docChanged) {
          return cur;
        }
        const { deleted, pos } = tr.mapping.mapResult(cur);
        return deleted ? null : pos;
      },
    },

    props: {
      decorations: drawCellSelection,

      handleDOMEvents: {
        mousedown: (view: EditorView, event: MouseEvent) => {
          handleMouseDown(view, event, key, isMobile);
          return false;
        },
      },

      createSelectionBetween(view: EditorView, $anchor: ResolvedPos, $head: ResolvedPos) {
        // If actively dragging, always preserve
        if (key.getState(view.state) !== null) {
          return view.state.selection;
        }

        // If we have a multi-cell selection, be smart about when to preserve it
        const selection = view.state.selection;
        if (isRicosCellSelection(selection) && !selection.isSingleCell()) {
          // If ProseMirror wants to create a collapsed selection (click),
          // allow it - the user is clicking to edit or select a single cell
          if ($anchor && $head && $anchor.pos === $head.pos) {
            return null;
          }
          // Otherwise, preserve our selection - this is likely a spurious
          // DOM observer event, not a real user interaction
          return selection;
        }

        return null;
      },

      handleKeyDown: (view: EditorView, event: KeyboardEvent) => {
        if (
          isRicosCellSelection(view.state.selection) &&
          !event.shiftKey &&
          !event.metaKey &&
          !event.ctrlKey &&
          !event.altKey &&
          event.key !== 'Escape'
        ) {
          editor.commands.setEditCell();
        }
        return false;
      },

      handlePaste,
    },

    appendTransaction(
      transactions: readonly Transaction[],
      oldState: EditorState,
      state: EditorState
    ) {
      let tr = fixTables(state, oldState);

      // Skip all table selection handling if the selection spans beyond a table
      const newSel = state.selection;
      const tableContext = findTable(newSel);
      if (tableContext) {
        const tableEnd = tableContext.pos + tableContext.node.nodeSize;
        const isSelectionBeyondTable = newSel.from < tableContext.pos || newSel.to > tableEnd;
        if (isSelectionBeyondTable) {
          return tr;
        }
      }

      // Only check for table navigation if it's a keyboard-driven transaction (not mouse click)
      const isKeyboardNavigation = transactions.some((t: Transaction) => {
        const meta = t.getMeta('pointer');
        return meta === undefined; // Keyboard events don't set pointer meta
      });

      if (isKeyboardNavigation && tableContext) {
        const oldSel = oldState.selection;
        const wasInTable = findTable(oldSel);

        if (!wasInTable && newSel instanceof TextSelection && !isRicosCellSelection(newSel)) {
          // Navigating into a table from outside — select the whole table
          const table = tableContext.node;
          const tableStart = tableContext.start;
          const map = TableMap.get(table);
          const rect = { left: 0, right: map.width, top: 0, bottom: map.height };
          const cellPositions = map.cellsInRect(rect);
          const cells = cellPositions.map(pos => state.doc.resolve(tableStart + pos));
          const tableSelection = new RicosCellSelection(cells, state.doc);

          if (!tr) {
            tr = state.tr;
          }
          tr?.setSelection(tableSelection);
        }
      }

      return normalizeSelection(state, tr);
    },
  });
};
