import type { EditorView } from './../../../tiptap/pm/view.js';

/**
 * Run `fn` and restore scroll positions of every scrolled ancestor.
 * Avoid `getComputedStyle` here: on a dirty table layout it can force a
 * restyle/layout per ancestor, which is visible at resize commit time.
 */
export function preserveScrollDuring(view: EditorView, fn: () => void): void {
  const scrollData: { element: Element; top: number; left: number }[] = [];

  let element: Element | null = view.dom;
  while (element) {
    const top = element.scrollTop;
    const left = element.scrollLeft;
    if (top !== 0 || left !== 0) {
      scrollData.push({ element, top, left });
    }
    element = element.parentElement;
  }

  const scrollingElement = document.scrollingElement;
  if (scrollingElement) {
    const top = scrollingElement.scrollTop;
    const left = scrollingElement.scrollLeft;
    if (top !== 0 || left !== 0) {
      scrollData.push({ element: scrollingElement, top, left });
    }
  }

  fn();

  for (const { element: el, top, left } of scrollData) {
    if (el.scrollTop !== top) {
      el.scrollTop = top;
    }
    if (el.scrollLeft !== left) {
      el.scrollLeft = left;
    }
  }
}
