import { isInlineTextOnly } from './../../../ricos-common-plugins/transaction-predicates/is-inline-text-only.js';
import { Plugin, PluginKey } from './../../../tiptap/pm/state.js';
import type { DecorationSet } from './../../../tiptap/pm/view.js';

import { cellEdgeDecorations } from '../decorations/index.js';

/**
 * Plugin that adds CSS classes and per-cell border CSS variables to table
 * cells at table edges, so borders render correctly with colspan/rowspan.
 *
 * `isInlineTextOnly` is safe as the reuse predicate because the decoration
 * output only depends on table structure, `tableData.cellSpacing`, and
 * per-cell border/ID attrs — none of which change under inline-text edits.
 */
export const cellEdgePlugin = () => {
  const key = new PluginKey<DecorationSet>('cell-edge');

  return new Plugin<DecorationSet>({
    key,
    state: {
      init: (_config, state) => cellEdgeDecorations(state.doc),
      apply: (tr, prev) => {
        if (!tr.docChanged) {
          return prev;
        }
        if (isInlineTextOnly(tr)) {
          return prev.map(tr.mapping, tr.doc);
        }
        return cellEdgeDecorations(tr.doc);
      },
    },
    props: {
      decorations(state) {
        return key.getState(state);
      },
    },
  });
};
