import { PluginKey } from './../../../tiptap/pm/state.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

/**
 * Plugin key for the column resizing plugin. Drag state lives in plugin
 * closures; the key is kept so ProseMirror can identify the plugin.
 */
export const columnResizingPluginKey = new PluginKey('tableColumnResizing');

/**
 * Plugin key for the row resizing plugin. See `columnResizingPluginKey`.
 */
export const rowResizingPluginKey = new PluginKey('tableRowResizing');

type ResizeInteractionState = {
  columnHover: boolean;
  rowHover: boolean;
  columnDrag: boolean;
  rowDrag: boolean;
};

const resizeInteractionStateByView = new WeakMap<EditorView, ResizeInteractionState>();

const getResizeInteractionState = (view: EditorView): ResizeInteractionState => {
  let resizeInteractionState = resizeInteractionStateByView.get(view);
  if (!resizeInteractionState) {
    resizeInteractionState = {
      columnHover: false,
      rowHover: false,
      columnDrag: false,
      rowDrag: false,
    };
    resizeInteractionStateByView.set(view, resizeInteractionState);
  }
  return resizeInteractionState;
};

export const setColumnResizeHoverActive = (view: EditorView, active: boolean): void => {
  getResizeInteractionState(view).columnHover = active;
};

export const setRowResizeHoverActive = (view: EditorView, active: boolean): void => {
  getResizeInteractionState(view).rowHover = active;
};

export const setColumnResizeDragActive = (view: EditorView, active: boolean): void => {
  getResizeInteractionState(view).columnDrag = active;
};

export const setRowResizeDragActive = (view: EditorView, active: boolean): void => {
  getResizeInteractionState(view).rowDrag = active;
};

export const clearResizeHoverActive = (view: EditorView): void => {
  const state = resizeInteractionStateByView.get(view);
  if (!state) {
    return;
  }
  state.columnHover = false;
  state.rowHover = false;
};

/**
 * Check if column resizing is currently active (hovering or dragging).
 */
export function isColumnResizingActive(view: EditorView): boolean {
  const state = resizeInteractionStateByView.get(view);
  return !!(state?.columnHover || state?.columnDrag);
}

/**
 * Check if row resizing is currently active (hovering or dragging).
 */
export function isRowResizingActive(view: EditorView): boolean {
  const state = resizeInteractionStateByView.get(view);
  return !!(state?.rowHover || state?.rowDrag);
}
