import type { EditorState, Transaction } from 'prosemirror-state';

import type { Node as ProseMirrorNode } from './../../../tiptap/pm/model.js';

import { applyBorderEdit, extractCellPositions } from '../../borders/canonical-remap.js';
import { type Side, buildCellGrid, getCellAt } from '../../borders/edge-detection.js';
import { TableQuery } from '../table-query.js';
import { isRicosCellSelection } from '../utilities/is-selection-type.js';

export const isOuterEdge = (
  cellData: { row: number; col: number; rowspan: number; colspan: number },
  side: Side,
  tableWidth: number,
  tableHeight: number,
  isCellInSelection: (row: number, col: number) => boolean
): boolean => {
  const { row, col, rowspan, colspan } = cellData;
  switch (side) {
    case 'top':
      return row === 0 || !isCellInSelection(row - 1, col);
    case 'bottom':
      return row + rowspan >= tableHeight || !isCellInSelection(row + rowspan, col);
    case 'left':
      return col === 0 || !isCellInSelection(row, col - 1);
    case 'right':
      return col + colspan >= tableWidth || !isCellInSelection(row, col + colspan);
    default:
      return false;
  }
};

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

type BorderStyle = { color?: string | undefined } | { width?: number | undefined };

interface CellWithPos {
  node: ProseMirrorNode;
  pos: number;
}

interface CellPosition {
  node: ProseMirrorNode;
  pos: number;
  row: number;
  col: number;
  rowspan: number;
  colspan: number;
}

function prepareBorderContext(state: EditorState) {
  const { selection } = state;
  const table = TableQuery.of(selection);
  if (!table || !isRicosCellSelection(selection)) {
    return null;
  }

  const tableNode = table.getNode();
  const tableStart = table.getStartPos();
  const allSelectedCells: CellWithPos[] = [];
  selection.forEachCell((node, pos) => allSelectedCells.push({ node, pos }));

  return { tableNode, tableStart, allSelectedCells };
}

function prepareGridContext(state: EditorState) {
  const ctx = prepareBorderContext(state);
  if (!ctx) {
    return null;
  }

  const { cells, width, height } = extractCellPositions(ctx.tableNode, ctx.tableStart);
  const selectedCellIds = new Set<string>();
  for (const { node } of ctx.allSelectedCells) {
    if (node.attrs.id) {
      selectedCellIds.add(node.attrs.id);
    }
  }

  const grid = buildCellGrid(cells, width, height);
  const isCellInSelection = (row: number, col: number): boolean => {
    const cell = getCellAt(grid, row, col);
    return cell ? selectedCellIds.has(cell.node.attrs.id) : false;
  };

  return { ...ctx, cells: cells as CellPosition[], width, height, isCellInSelection };
}

// ---------------------------------------------------------------------------
// All selected cells
// ---------------------------------------------------------------------------

function setCellBorderStyle(style: BorderStyle, clear: boolean) {
  return (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const ctx = prepareBorderContext(state);
    if (!ctx) {
      return false;
    }
    if (!dispatch) {
      return true;
    }
    const tr = state.tr;
    applyBorderEdit(tr, ctx.tableNode, ctx.tableStart, ctx.allSelectedCells, null, style, clear);
    dispatch(tr);
    return true;
  };
}

export const setCellBorderColor = (color: string | undefined) =>
  setCellBorderStyle({ color }, color === undefined);

export const setCellBorderWidth = (width: number | undefined) =>
  setCellBorderStyle({ width }, false);

// ---------------------------------------------------------------------------
// Outsider (outer edge) cells — each side separately
// ---------------------------------------------------------------------------

function setOutsiderCellsBorderStyle(style: BorderStyle, clear: boolean) {
  return (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const ctx = prepareGridContext(state);
    if (!ctx) {
      return false;
    }
    if (!dispatch) {
      return true;
    }

    const sides: Side[] = ['top', 'bottom', 'left', 'right'];
    const outerEdgeCells = new Map<Side, CellWithPos[]>(sides.map(s => [s, []]));

    for (const { node, pos } of ctx.allSelectedCells) {
      const cellData = ctx.cells.find(c => c.node.attrs.id === node.attrs.id);
      if (!cellData) {
        continue;
      }
      for (const side of sides) {
        if (isOuterEdge(cellData, side, ctx.width, ctx.height, ctx.isCellInSelection)) {
          outerEdgeCells.get(side)!.push({ node, pos });
        }
      }
    }

    const tr = state.tr;
    for (const side of sides) {
      const cellsForSide = outerEdgeCells.get(side)!;
      if (cellsForSide.length > 0) {
        const $pos = tr.doc.resolve(ctx.tableStart);
        const currentTable = $pos.node($pos.depth);
        if (currentTable?.type.spec.tableRole === 'table') {
          applyBorderEdit(tr, currentTable, ctx.tableStart, cellsForSide, side, style, clear);
        }
      }
    }

    dispatch(tr);
    return true;
  };
}

export const setOutsiderCellsBorderColor = (color: string | undefined) =>
  setOutsiderCellsBorderStyle({ color }, color === undefined);

export const setOutsiderCellsBorderWidth = (width: number | undefined) =>
  setOutsiderCellsBorderStyle({ width }, false);

// ---------------------------------------------------------------------------
// Single side — only cells on the outer edge of that side
// ---------------------------------------------------------------------------

function setCellBorderBySideStyle(side: Side, style: BorderStyle, clear: boolean) {
  return (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const ctx = prepareGridContext(state);
    if (!ctx) {
      return false;
    }
    if (!dispatch) {
      return true;
    }

    const outerCells: CellWithPos[] = [];
    for (const { node, pos } of ctx.allSelectedCells) {
      const cellData = ctx.cells.find(c => c.node.attrs.id === node.attrs.id);
      if (!cellData) {
        continue;
      }
      if (isOuterEdge(cellData, side, ctx.width, ctx.height, ctx.isCellInSelection)) {
        outerCells.push({ node, pos });
      }
    }

    const tr = state.tr;
    if (outerCells.length > 0) {
      applyBorderEdit(tr, ctx.tableNode, ctx.tableStart, outerCells, side, style, clear);
    }
    dispatch(tr);
    return true;
  };
}

export const setCellBorderColorBySide = (side: Side, color: string | undefined) =>
  setCellBorderBySideStyle(side, { color }, color === undefined);

export const setCellBorderWidthBySide = (side: Side, width: number | undefined) =>
  setCellBorderBySideStyle(side, { width }, false);

// ---------------------------------------------------------------------------
// Inner horizontal — cells with a selected neighbor above
// ---------------------------------------------------------------------------

function setInnerHorizontalCellsBorderStyle(style: BorderStyle, clear: boolean) {
  return (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const ctx = prepareGridContext(state);
    if (!ctx) {
      return false;
    }
    if (!dispatch) {
      return true;
    }

    const innerCells = ctx.allSelectedCells.filter(({ node }) => {
      const cellData = ctx.cells.find(c => c.node.attrs.id === node.attrs.id);
      return cellData && cellData.row > 0 && ctx.isCellInSelection(cellData.row - 1, cellData.col);
    });

    const tr = state.tr;
    if (innerCells.length > 0) {
      applyBorderEdit(tr, ctx.tableNode, ctx.tableStart, innerCells, 'top', style, clear);
    }
    dispatch(tr);
    return true;
  };
}

export const setInnerHorizontalCellsBorderColor = (color: string | undefined) =>
  setInnerHorizontalCellsBorderStyle({ color }, color === undefined);

export const setInnerHorizontalCellsBorderWidth = (width: number | undefined) =>
  setInnerHorizontalCellsBorderStyle({ width }, false);

// ---------------------------------------------------------------------------
// Inner vertical — cells with a selected neighbor to the left
// ---------------------------------------------------------------------------

function setInnerVerticalCellsBorderStyle(style: BorderStyle, clear: boolean) {
  return (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const ctx = prepareGridContext(state);
    if (!ctx) {
      return false;
    }
    if (!dispatch) {
      return true;
    }

    const innerCells = ctx.allSelectedCells.filter(({ node }) => {
      const cellData = ctx.cells.find(c => c.node.attrs.id === node.attrs.id);
      return cellData && cellData.col > 0 && ctx.isCellInSelection(cellData.row, cellData.col - 1);
    });

    const tr = state.tr;
    if (innerCells.length > 0) {
      applyBorderEdit(tr, ctx.tableNode, ctx.tableStart, innerCells, 'left', style, clear);
    }
    dispatch(tr);
    return true;
  };
}

export const setInnerVerticalCellsBorderColor = (color: string | undefined) =>
  setInnerVerticalCellsBorderStyle({ color }, color === undefined);

export const setInnerVerticalCellsBorderWidth = (width: number | undefined) =>
  setInnerVerticalCellsBorderStyle({ width }, false);
