import { getElementScale } from './../../../_shared/get-element-scale.js';
import type { Editor } from './../../../tiptap/core/index.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

import { createResizeDragController, triggerResizeTick } from './resize-drag-controller.js';
import {
  isColumnResizingActive,
  rowResizingPluginKey,
  setRowResizeDragActive,
} from './resizing-plugin-keys.js';
import type { RowResizingDragInfo, RowResizingDragState, RowResizingRowInfo } from './types.js';

type StartArgs = {
  tablePosition: number;
  rowInfo: RowResizingRowInfo;
  nextRowInfo: RowResizingRowInfo | undefined;
  event: PointerEvent;
};

const startRowResizeDragByEditor = new WeakMap<
  Editor,
  (view: EditorView, args: StartArgs) => boolean
>();

export const getStartRowResizeDrag = (editor: Editor) => startRowResizeDragByEditor.get(editor);

export const rowResizingPlugin = ({ editor }: { editor: Editor }) => {
  let dragRowElement: HTMLElement | null = null;
  let dragNextRowElement: HTMLElement | null = null;
  let latestRowNewHeight = 0;
  let latestNextRowNewHeight: number | undefined = undefined;

  const controller = createResizeDragController<StartArgs, RowResizingDragState>(editor, {
    pluginKey: rowResizingPluginKey,
    setActive: setRowResizeDragActive,
    isOtherActive: isColumnResizingActive,

    begin(view, { tablePosition, rowInfo, nextRowInfo, event }) {
      const dragRowInfo = getDragRowInfo(view, rowInfo);
      const dragNextRowInfo = nextRowInfo ? getDragRowInfo(view, nextRowInfo) : undefined;
      const rowDom = view.nodeDOM(dragRowInfo.position) as HTMLElement | null;
      if (!rowDom) {
        return null;
      }
      const scale = getElementScale(rowDom);

      dragRowElement = rowDom;
      dragNextRowElement = dragNextRowInfo
        ? (view.nodeDOM(dragNextRowInfo.position) as HTMLElement | null)
        : null;
      latestRowNewHeight = dragRowInfo.newHeight;
      latestNextRowNewHeight = dragNextRowInfo?.newHeight;

      return {
        rowInfo: dragRowInfo,
        initialTotalHeight: dragRowInfo.newHeight + (dragNextRowInfo?.newHeight ?? 0),
        initialRowHeight: dragRowInfo.newHeight,
        nextRowInfo: dragNextRowInfo,
        tablePosition,
        startY: event.pageY / scale.scaleY,
        scale,
      };
    },

    applyFrame(view, event, dragState) {
      const scaledPageY = event.pageY / dragState.scale.scaleY;
      const deltaY = scaledPageY - dragState.startY;
      const newRowHeight = Math.max(
        dragState.initialRowHeight + deltaY,
        dragState.rowInfo.minHeight
      );
      const nextRowPotentialHeight = dragState.initialTotalHeight - newRowHeight;
      const newNextRowHeight = dragState.nextRowInfo
        ? Math.max(nextRowPotentialHeight, dragState.nextRowInfo.minHeight)
        : undefined;

      latestRowNewHeight = newRowHeight;
      latestNextRowNewHeight = newNextRowHeight;

      if (dragRowElement) {
        dragRowElement.style.height = `${newRowHeight}px`;
      }
      if (dragNextRowElement && newNextRowHeight !== undefined) {
        dragNextRowElement.style.height = `${newNextRowHeight}px`;
      }

      triggerResizeTick(view);
      event.preventDefault();
      event.stopPropagation();
    },

    commit(view, dragState) {
      const finalRowHeight = latestRowNewHeight;
      const finalNextRowHeight = latestNextRowNewHeight;
      dragRowElement = null;
      dragNextRowElement = null;

      const tr = view.state.tr.setMeta('pointer', true);
      tr.setNodeAttribute(dragState.rowInfo.position, 'height', finalRowHeight);
      if (dragState.nextRowInfo && finalNextRowHeight !== undefined) {
        tr.setNodeAttribute(dragState.nextRowInfo.position, 'height', finalNextRowHeight);
      }
      view.dispatch(tr);
    },
  });

  startRowResizeDragByEditor.set(editor, controller.start);
  return controller.plugin;
};

const getDragRowInfo = (
  view: EditorView,
  { position, index }: RowResizingRowInfo
): RowResizingDragInfo => {
  const rowElement = view.nodeDOM(position) as HTMLTableRowElement | null;
  const minHeight = rowElement ? calculateMinRowHeight(rowElement) : 0;
  return {
    position,
    index,
    newHeight: Math.max(rowElement?.offsetHeight ?? 0, minHeight),
    minHeight,
  };
};

function calculateMinRowHeight(rowElement: HTMLTableRowElement): number {
  const originalHeight = rowElement.style.height;
  rowElement.style.height = '0px';
  const minHeight = rowElement.offsetHeight;
  rowElement.style.height = originalHeight;
  return Math.max(minHeight, 0);
}
