type TableCellStylePreview = {
  cellDecorations: {
    from: number;
    to: number;
    className?: string;
    style?: string;
  }[];
  /**
   * CSS variables set on the editor root while the preview is active. Only the
   * names listed in `PREVIEW_ROOT_STYLE_NAMES` below are honoured; everything
   * else is ignored.
   */
  rootStyle?: Record<string, string>;
};

