import { TIPTAP_TABLE_CELL_TYPE, TIPTAP_TABLE_HEADER_CELL_TYPE } from './../../../ricos-content/consts.js';
import type { RicosServices, TiptapEditor } from './../../../ricos-types/index.js';
import { Plugin, PluginKey, TextSelection } from './../../../tiptap/pm/state.js';
import { DecorationSet } from './../../../tiptap/pm/view.js';

import { isInTable } from '../commands/queries.js';
import { TRANSACTION_META_KEYS } from '../consts.js';
import { cellEditingDecorations } from '../decorations/index.js';
import { isRicosCellSelection } from '../utilities/is-selection-type.js';

export const cellStatesPlugin = (
  editor: TiptapEditor,
  _services: RicosServices,
  isMobile?: boolean
) => {
  const key = new PluginKey('cell-states');
  return new Plugin({
    key,
    state: {
      init: () => {
        return {};
      },
      apply(tr, prev, oldState, newState) {
        if (!isInTable(newState)) {
          return {};
        }
        if (isRicosCellSelection(newState.selection)) {
          return {};
        }

        const { pos: editCell } = tr.getMeta(TRANSACTION_META_KEYS.EDITING_CELL) || {};
        const { pos: selectCell } = tr.getMeta(TRANSACTION_META_KEYS.SELECTED_CELL) || {};
        if (newState.selection.ranges.length > 1) {
          return {};
        } else if (selectCell) {
          return {
            selectCell,
          };
        } else if (editCell) {
          return {
            editCell,
          };
        }
        return prev;
      },
    },

    props: {
      handleDOMEvents: {
        mousedown: (view, event) => {
          if (isMobile || event.button !== 0) {
            return false;
          }
          // Check if we clicked directly on the cell element (TD/TH) or its wrapper
          // vs clicking on content inside the cell
          let target = event.target as HTMLElement;
          const clickTarget = event.target as HTMLElement;

          // Walk up to see if we hit a TD/TH directly (bounds click)
          // or if we're inside content elements
          let isClickOnBounds = false;
          let cellElement: HTMLElement | null = null;

          while (target && target !== view.dom) {
            const tagName = target.tagName;

            if (tagName === 'TD' || tagName === 'TH') {
              cellElement = target;
              // Consider it a bounds click if:
              // 1. We clicked directly on TD/TH
              // 2. We clicked on the cell wrapper div (first child div of TD/TH)
              // 3. We clicked on a node view wrapper (for images, etc)
              if (clickTarget === target) {
                isClickOnBounds = true;
              } else if (clickTarget.tagName === 'DIV' && clickTarget.parentElement === target) {
                // Clicked on a direct child div of the cell (likely the wrapper)
                isClickOnBounds = true;
              } else {
                // Check if we clicked on a node view wrapper (for images, etc)
                // These typically have data-node-view-wrapper or similar attributes
                const isNodeView =
                  clickTarget.hasAttribute('data-node-view-wrapper') ||
                  clickTarget.classList.contains('node-view-wrapper') ||
                  clickTarget.hasAttribute('data-node-view-content');

                if (isNodeView) {
                  isClickOnBounds = true;
                }
              }
              break;
            }

            target = target.parentElement as HTMLElement;
          }

          if (!cellElement) {
            return false;
          }

          // If clicking on content (not bounds), allow default behavior
          if (!isClickOnBounds) {
            return false;
          }

          // We clicked on cell bounds - find the cell position
          const pos = view.posAtDOM(cellElement, 0);
          if (pos === null || pos === undefined) {
            return false;
          }

          // Find the actual cell node position
          let cellPos: number | null = null;
          const $pos = view.state.doc.resolve(pos);

          // Walk up the resolved position to find the table cell (TD or TH)
          for (let d = $pos.depth; d > 0; d--) {
            const nodeType = $pos.node(d).type.name;
            if (nodeType === TIPTAP_TABLE_CELL_TYPE || nodeType === TIPTAP_TABLE_HEADER_CELL_TYPE) {
              cellPos = $pos.before(d);
              break;
            }
          }

          if (cellPos === null) {
            return false;
          }

          // Check if this cell is already selected
          const { selection } = view.state;

          if (isRicosCellSelection(selection)) {
            const isSingleCell = selection.$anchorCell.pos === selection.$headCell.pos;

            if (isSingleCell && selection.$anchorCell.pos === cellPos) {
              // Cell already selected, place cursor at END of cell content
              event.preventDefault();

              // Find the end of the cell content
              const cellNode = view.state.doc.nodeAt(cellPos);
              if (!cellNode) {
                return false;
              }

              // Position at the end of the cell (before the closing tag)
              const cellContentEnd = cellPos + cellNode.nodeSize - 1;

              const tr = view.state.tr.setSelection(
                TextSelection.near(view.state.doc.resolve(cellContentEnd), -1)
              );
              view.dispatch(tr);

              // Focus the editor to ensure cursor is visible
              view.focus();
              return true;
            }
          }

          // Cell not selected, prevent default and select it
          event.preventDefault();
          editor.commands.setCellSelection(cellPos);

          // Focus the editor so keyboard shortcuts work
          editor.view.focus();
          return true;
        },
      },

      decorations(state) {
        const tablePluginState = state && key.getState(state);
        if (tablePluginState.editCell) {
          const editDecorations = cellEditingDecorations(tablePluginState.editCell);
          return DecorationSet.create(state.doc, editDecorations);
        }
      },
    },
  });
};
