/* oxlint-disable fp/no-loops */
import { deepEqual } from './../../../_shared/deep-equal.js';
import type { SingleCommands } from './../../../tiptap/core/index.js';
import type { Node as ProseMirrorNode } from './../../../tiptap/pm/model.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

import { cellAround } from '../commands/queries.js';
import { TableMap } from '../tablemap.js';

export function updateHandle(view: $TSFixMe, value: $TSFixMe, key: $TSFixMe) {
  view.dispatch(view.state.tr.setMeta(key, { setHandle: value }));
}

export function resetHandle(view: $TSFixMe, key: $TSFixMe) {
  const pluginState = key.getState(view.state);
  if (pluginState.activeHandle > -1 && !pluginState.dragging) {
    updateHandle(view, -1, key);
  }
}

export function domCellAround(target: $TSFixMe) {
  // oxlint-disable-next-line fp/no-loops
  while (target && target.nodeName !== 'TD' && target.nodeName !== 'TH') {
    // oxlint-disable-next-line no-param-reassign
    target = target.classList.contains('ProseMirror') ? null : target.parentNode;
  }
  return target;
}

export function edgeCell(view: $TSFixMe, event: $TSFixMe, side: $TSFixMe, isVertical = false) {
  const found = view.posAtCoords({ left: event.clientX, top: event.clientY });
  if (!found) {
    return -1;
  }
  const { inside } = found;
  const $cell = cellAround(view.state.doc.resolve(inside + 1));
  if (!$cell) {
    return -1;
  }
  const direction = isVertical ? 'bottom' : 'right';
  if (side === direction) {
    return $cell.pos;
  }
  const map = TableMap.get($cell.node(-1));
  const start = $cell.start(-1);
  const index = map.map.indexOf($cell.pos - start);
  return index % map.width === 0 ? -1 : start + map.map[index - 1];
}

export function updateColumns({
  node,
  colgroup,
  table,
  cellMinWidth,
  commands,
  overrideCol,
  overrideValue,
  shouldUpdateState,
}: {
  node: ProseMirrorNode;
  colgroup: Element;
  table: HTMLElement;
  cellMinWidth: number;
  commands: SingleCommands;
  overrideCol?: number;
  overrideValue?: number;
  shouldUpdateState: boolean;
}) {
  let totalWidth = 0;
  let nextDOM = colgroup.firstChild;

  // Read from table-level dimensions (same as viewer) for consistency
  const colsWidthRatio = node.attrs.dimensions?.colsWidthRatio || [];

  // Calculate actual column count from first row
  const row = node.firstChild;
  let actualColumnCount = 0;
  if (row) {
    for (let i = 0; i < row.childCount; i++) {
      actualColumnCount += row.child(i).attrs.colspan || 1;
    }
  }

  // Use table-level widths if available (primary path - consistent with viewer)
  if (colsWidthRatio.length > 0 && colsWidthRatio.length === actualColumnCount) {
    const spacing = (node.attrs.tableData?.cellSpacing as number | undefined) ?? 0;
    for (let col = 0; col < colsWidthRatio.length; col++) {
      const rawWidth = overrideCol === col ? overrideValue : colsWidthRatio[col];
      const baseWidth = rawWidth ? Math.max(rawWidth, cellMinWidth) : cellMinWidth;
      // Add spacing to width for non-first columns (transparent borders increase cell width)
      const hasWidth = col > 0 && spacing > 0 ? baseWidth + spacing : baseWidth;
      const cssWidth = hasWidth + 'px';
      totalWidth += hasWidth;

      if (!nextDOM) {
        const colElement = document.createElement('col');
        colElement.style.width = cssWidth;
        colgroup.appendChild(colElement);
      } else {
        // @ts-expect-error
        if (nextDOM.style.width !== cssWidth) {
          // @ts-expect-error
          nextDOM.style.width = cssWidth;
        }
        nextDOM = nextDOM.nextSibling;
      }
    }
  } else {
    // Fall back to cell-level colwidth arrays (for backward compatibility or tables without dimensions)
    const spacing = (node.attrs.tableData?.cellSpacing as number | undefined) ?? 0;
    const row = node.firstChild;
    if (row === null) {
      return;
    }

    let fixedWidth = true;
    for (let i = 0, col = 0; i < row.childCount; i++) {
      const { colspan, colwidth } = row.child(i).attrs;
      for (let j = 0; j < colspan; j++, col++) {
        const rawWidth = overrideCol === col ? overrideValue : colwidth && colwidth[j];
        const baseWidth = rawWidth ? Math.max(rawWidth, cellMinWidth) : null;
        // Add spacing to width for non-first columns (transparent borders increase cell width)
        const hasWidth = baseWidth && col > 0 && spacing > 0 ? baseWidth + spacing : baseWidth;
        const cssWidth = hasWidth ? hasWidth + 'px' : '';
        totalWidth += hasWidth || cellMinWidth;
        if (!hasWidth) {
          fixedWidth = false;
        }
        if (!(nextDOM instanceof HTMLElement)) {
          const colElement = document.createElement('col');
          colElement.style.width = cssWidth;
          colgroup.appendChild(colElement);
        } else {
          if (nextDOM.style.width !== cssWidth) {
            nextDOM.style.width = cssWidth;
          }
          nextDOM = nextDOM.nextSibling;
        }
      }
    }

    // Only apply minWidth fallback if using cell-level widths and not all columns have explicit widths
    if (!fixedWidth) {
      table.style.width = '';
      table.style.minWidth = totalWidth + 'px';

      // Clean up extra cols and exit early
      while (nextDOM) {
        const after = nextDOM.nextSibling;
        if (nextDOM.parentNode) {
          nextDOM.parentNode.removeChild(nextDOM);
        }
        nextDOM = after;
      }

      if (shouldUpdateState) {
        updateColsWidthAttrs(colgroup, node, commands);
      }
      return;
    }
  }

  // Clean up extra cols
  while (nextDOM) {
    const after = nextDOM.nextSibling;
    if (nextDOM.parentNode === null) {
      return;
    }
    nextDOM.parentNode.removeChild(nextDOM);
    nextDOM = after;
  }

  if (shouldUpdateState) {
    // If we'll start updating state while dragging the live feedback will be lost, because state changes break that.
    updateColsWidthAttrs(colgroup, node, commands);
  }

  // Always use fixed width when we have explicit widths (from table-level or complete cell-level)
  table.style.width = totalWidth + 'px';
  table.style.minWidth = '';
}

function updateColsWidthAttrs(colgroup: Element, table: ProseMirrorNode, commands: SingleCommands) {
  const spacing = (table.attrs.tableData?.cellSpacing as number | undefined) ?? 0;

  // Read widths from DOM and remove spacing compensation for non-first columns
  const colsWidth = Array.from(colgroup.children).map((col, index) => {
    const width = (col as HTMLElement).offsetWidth;
    // Remove spacing that was added to non-first columns
    return index > 0 && spacing > 0 ? width - spacing : width;
  });

  // Min widths should also account for spacing when applied
  const colsMinWidth = colsWidth.map((width, index) => {
    const minBase = Math.min(width, 120);
    // Add spacing back for storage so it's applied consistently
    return index > 0 && spacing > 0 ? minBase : minBase;
  });

  if (
    !deepEqual(table.attrs.dimensions?.colsWidthRatio, colsWidth) ||
    !deepEqual(table.attrs.dimensions?.colsMinWidth, colsMinWidth)
  ) {
    try {
      commands.updateNodeAttrsById(table.attrs.id, {
        ...table.attrs,
        dimensions: {
          ...table.attrs.dimensions,
          colsWidthRatio: colsWidth,
          colsMinWidth,
        },
      });
    } catch (e) {
      console.error('could not update node attributes by id', e);
    }
  }
}

/**
 * Find the table HTML element from a table position in the document.
 */
export const getTableElement = (
  view: EditorView,
  tablePosition: number
): HTMLTableElement | null => {
  try {
    const dom = view.domAtPos(tablePosition + 1).node;
    let element: Node | null = dom;
    while (element && element.nodeName !== 'TABLE') {
      element = element.parentNode;
    }
    return element as HTMLTableElement;
  } catch {
    return null;
  }
};
