import type { EditorState, Transaction } from 'prosemirror-state';
import { TextSelection } from 'prosemirror-state';

import { TRANSACTION_META_KEYS } from '../consts.js';
import { RicosCellSelection, getCellsInExpandedRect } from '../plugins/cellselection.js';
import { TableQuery } from '../table-query.js';
import { removeRow, selectColumn, selectRow, selectTable } from './mutations.js';
import { selectedRect } from './queries.js';

export const setCellSelection =
  (pos: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    if (dispatch) {
      const selection = RicosCellSelection.create(tr.doc, pos);
      tr.setMeta(TRANSACTION_META_KEYS.SELECTED_CELL, { pos });
      tr.setSelection(selection);
      dispatch(tr);
    }
    return true;
  };

export const selectColumnAtIndex =
  (index: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    tr.setMeta(TRANSACTION_META_KEYS.SELECT_COLUMN, index);
    const rect = selectedRect(state);
    dispatch?.(selectColumn(tr, rect, index));
    return true;
  };

export const selectColumnCmd =
  () =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const rect = selectedRect(state);
    dispatch?.(selectColumn(tr, rect, rect.left));
    return true;
  };

