export const selectRows =
  (fromRow: number, toRow: number, tablePos: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const $tablePos = tr.doc.resolve(tablePos);
    const tempSelection = TextSelection.create(tr.doc, $tablePos.pos);
    const table = TableQuery.of(tempSelection);
    if (!table) {
      return false;
    }

    const initialRect = {
      left: 0,
      right: table.map.width,
      top: fromRow,
      bottom: toRow + 1,
    };
    const cells = getCellsInExpandedRect(tr.doc, table.getStartPos(), table.map, initialRect);

    const selection = new RicosCellSelection(cells, tr.doc);
    if (dispatch) {
      dispatch(tr.setSelection(selection));
    }
    return true;
  };

export const selectColumns =
  (fromCol: number, toCol: number, tablePos: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const $tablePos = tr.doc.resolve(tablePos);
    const tempSelection = TextSelection.create(tr.doc, $tablePos.pos);
    const table = TableQuery.of(tempSelection);
    if (!table) {
      return false;
    }

    const initialRect = {
      left: fromCol,
      right: toCol + 1,
      top: 0,
      bottom: table.map.height,
    };
    const cells = getCellsInExpandedRect(tr.doc, table.getStartPos(), table.map, initialRect);

    const selection = new RicosCellSelection(cells, tr.doc);
    if (dispatch) {
      dispatch(tr.setSelection(selection));
    }
    return true;
  };

export const deleteRowAtIndex =
  (index: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const rect = selectedRect(state);
    removeRow(tr, rect, index);
    dispatch?.(tr);
    return true;
  };

export const selectWholeTable =
  () =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    return selectTable(state, dispatch);
  };
