import type { EditorState, Transaction } from 'prosemirror-state';
import { Selection, TextSelection } from 'prosemirror-state';

import type { Node as ProseMirrorNode } from './../../../tiptap/pm/model.js';

import { canonicalizeBorders } from '../../borders/canonical-remap.js';
import { TRANSACTION_META_KEYS } from '../consts.js';
import { TableQuery } from '../table-query.js';
import { createTable } from '../utilities/create-table.js';
import { findTable } from '../utilities/find-table.js';
import { isRicosCellSelection } from '../utilities/is-selection-type.js';
import { addColumn, addRow, selectColumn, selectRow } from './mutations.js';
import { cellAround, getTableRectFromDoc, selectedRect } from './queries.js';

export const insertTable =
  ({ rows = 3, cols = 3, withHeaderRow = true } = {}) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const node = createTable(state.schema, rows, cols, withHeaderRow);

    if (dispatch) {
      const offset = tr.selection.anchor + 1;

      tr.replaceSelectionWith(node)
        .scrollIntoView()
        .setSelection(TextSelection.near(tr.doc.resolve(offset)));
      dispatch(tr);
    }

    return true;
  };

export const setCellAttribute =
  (name: string, value: unknown) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const { selection } = state;
    if (!isRicosCellSelection(selection)) {
      return false;
    }
    selection.forEachCell((node: ProseMirrorNode, pos: number) => {
      if (node.attrs[name] !== value) {
        tr.setNodeMarkup(pos, null, { ...node.attrs, [name]: value });
      }
    });
    dispatch?.(tr);

    return true;
  };

export const updateCellAttribute =
  (name: string, value: unknown) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const { selection } = state;
    if (!isRicosCellSelection(selection)) {
      return false;
    }
    selection.forEachCell((node: ProseMirrorNode, pos: number) => {
      if (node.attrs[name] !== value) {
        tr.setNodeMarkup(pos, null, {
          ...node.attrs,
          [name]: { ...(node.attrs[name] || {}), ...(value ?? {}) },
        });
      }
    });
    dispatch?.(tr);

    return true;
  };

export const toggleTableAttribute =
  (name: string) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const parentTable = findTable(state.selection);
    if (parentTable) {
      const { tr } = state;
      const table = parentTable.node;
      const existingTableData = table.attrs.tableData || {};
      tr.setNodeMarkup(parentTable.pos, undefined, {
        ...table.attrs,
        tableData: {
          ...existingTableData,
          [name]: !existingTableData[name],
        },
      });
      dispatch?.(tr);
    }
    return true;
  };

export const setTableAltText =
  (text: string) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const parentTable = findTable(state.selection);
    if (parentTable) {
      const { tr } = state;
      const table = parentTable.node;
      const existingTableData = table.attrs.tableData || {};
      tr.setNodeMarkup(parentTable.pos, undefined, {
        ...table.attrs,
        tableData: {
          ...existingTableData,
          altText: text || undefined,
        },
      });
      dispatch?.(tr);
    }
    return true;
  };

export const setCellSpacing =
  (spacing: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const table = TableQuery.of(state.selection);
    if (!table) {
      return false;
    }

    const tableNode = table.getNode();
    const tablePos = table.getStartPos() - 1;

    // Ensure tableData is an object, preserving existing fields
    const existingTableData = tableNode.attrs.tableData || {};
    tr.setNodeMarkup(tablePos, null, {
      ...tableNode.attrs,
      tableData: {
        ...existingTableData,
        cellSpacing: spacing,
      },
    });

    dispatch?.(tr);
    return true;
  };

export const setCellPadding =
  (padding: number | number[]) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const table = TableQuery.of(state.selection);
    if (!table) {
      return false;
    }

    const tableNode = table.getNode();
    const tablePos = table.getStartPos() - 1;

    // Ensure tableData is an object, preserving existing fields
    const existingTableData = tableNode.attrs.tableData || {};
    // Set padding as an array - either use the provided array or convert single number to array
    const paddingArray = Array.isArray(padding) ? padding : [padding, padding, padding, padding];
    tr.setNodeMarkup(tablePos, null, {
      ...tableNode.attrs,
      tableData: {
        ...existingTableData,
        cellPadding: paddingArray,
      },
    });

    dispatch?.(tr);
    return true;
  };

export const setEditCell =
  () =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const $anchor = cellAround(state.selection.$anchor);
    if ($anchor) {
      tr.setMeta(TRANSACTION_META_KEYS.EDITING_CELL, { pos: $anchor });
      const selection = Selection.near(state.selection.$head, -1);
      tr.setSelection(selection);
      dispatch?.(tr);
      return true;
    }
    return false;
  };

export const clearCell =
  () =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const { selection } = state;

    let hasCleared = false;

    if (isRicosCellSelection(selection)) {
      const paragraphType = state.schema.nodes.PARAGRAPH;
      const { doc } = state;

      // Sort positions in reverse order to avoid position shifting
      const positions = Array.from(selection.cellPositions).sort((a, b) => b - a);

      for (const pos of positions) {
        const node = doc.nodeAt(pos);
        if (
          node &&
          (node.childCount > 1 ||
            // Non-leaf node has empty content nodeSize of 2 (opening and closing tags)
            (node.childCount === 1 && node.firstChild!.nodeSize > 2))
        ) {
          hasCleared = true;
          const cellStart = pos + 1;
          const cellEnd = pos + node.nodeSize - 1;
          tr.replaceWith(cellStart, cellEnd, paragraphType.create());
        }
      }

      dispatch?.(tr);
      return hasCleared;
    }

    return false;
  };

export const setTableRowHeight =
  (height: number, pos: number, node: ProseMirrorNode) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    tr.setNodeMarkup(pos, undefined, { ...node.attrs, height });
    dispatch?.(tr);
    return true;
  };

export const distributeRows =
  () =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const table = TableQuery.of(state.selection);
    if (table) {
      const rows = table.getRowsIndexesInSelection();
      const tableAttrs = table.getNode().attrs;
      const totalHeight = [...tableAttrs.dimensions.rowsHeight]
        .splice(rows[0], rows[rows.length - 1])
        .reduce((curr, acc) => curr + acc, 0);
      const newHeight = totalHeight / rows.length;
      table.getNode().content.forEach((node, pos, index) => {
        rows.includes(index) &&
          tr.setNodeMarkup(pos + table.getStartPos(), undefined, {
            ...node.attrs,
            height: newHeight,
          });
      });
      dispatch?.(tr);
      return true;
    }
    return false;
  };

export const distributeColumns =
  () =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const tr = state.tr;
    const table = TableQuery.of(state.selection);
    if (!table) {
      return false;
    }

    const cols = table.getColsIndexesInSelection();
    if (cols.length === 0) {
      return false;
    }

    const tableNode = table.getNode();
    const tableStart = table.getStartPos();
    const tableMap = table.map;
    const dimensions = tableNode.attrs.dimensions || {};

    const existingColsWidthRatio = dimensions.colsWidthRatio || Array(tableMap.width).fill(100);

    const totalWidth = cols.reduce(
      (sum, colIndex) => sum + (existingColsWidthRatio[colIndex] || 100),
      0
    );
    const widthPerColumn = totalWidth / cols.length;

    const colsWidthRatio = [...existingColsWidthRatio];
    const colsMinWidth = dimensions.colsMinWidth
      ? [...dimensions.colsMinWidth]
      : Array(tableMap.width).fill(100);

    cols.forEach(colIndex => {
      colsWidthRatio[colIndex] = widthPerColumn;
      colsMinWidth[colIndex] = Math.min(widthPerColumn, 120);
    });

    tr.setNodeMarkup(tableStart - 1, null, {
      ...tableNode.attrs,
      dimensions: {
        ...dimensions,
        colsWidthRatio,
        colsMinWidth,
      },
    });

    dispatch?.(tr);
    return true;
  };

export const addColumnAtIndex =
  (index: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    if (!dispatch) {
      return true;
    }
    const rect = selectedRect(state);
    const tr = addColumn(state.tr, rect, index);
    const newRect = getTableRectFromDoc(tr.doc, rect.tableStart);
    canonicalizeBorders(tr, newRect.table, newRect.tableStart);
    dispatch(selectColumn(tr, newRect, index));
    return true;
  };

export const addRowAtIndex =
  (index: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    if (!dispatch) {
      return true;
    }
    const rect = selectedRect(state);
    const tr = addRow(state.tr, rect, index);
    const newRect = getTableRectFromDoc(tr.doc, rect.tableStart);
    canonicalizeBorders(tr, newRect.table, newRect.tableStart);
    dispatch(selectRow(tr, newRect, index));
    return true;
  };
