import {
  TIPTAP_TABLE_CELL_TYPE,
  TIPTAP_TABLE_HEADER_CELL_TYPE,
  TIPTAP_TABLE_ROW_TYPE,
} from './../../ricos-content/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../../ricos-types/index.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

export const tableRowExtension = createRicosNodeExtension({
  groups: [],
  type: 'html-node',
  reconfigure: (
    config: NodeConfig,
    _extensions: RicosExtension[],
    _props: ExtensionProps,
    settings: Record<string, unknown>
  ) => ({
    ...config,
    addOptions: () => settings,
  }),
  name: TIPTAP_TABLE_ROW_TYPE,
  createExtensionConfig() {
    return {
      name: this.name,
      tableRole: 'row',
      // It's not TableRowNodeChildrenPattern, because ProseMirror state has two types of cells for some reason :!?:(
      content: `(${TIPTAP_TABLE_CELL_TYPE} | ${TIPTAP_TABLE_HEADER_CELL_TYPE})*`,
      addAttributes: () => ({
        height: {
          default: 47,
          parseHTML: element => element.style.height && parseInt(element.style.height),
          renderHTML: attributes => {
            return {
              style: `height: ${attributes.height}px`,
            };
          },
        },
      }),
      parseHTML() {
        return [{ tag: 'tr' }];
      },

      renderHTML({ HTMLAttributes }) {
        return ['tr', HTMLAttributes, 0];
      },

      addNodeView() {
        return ({ node, HTMLAttributes }) => {
          const dom = document.createElement('tr');
          Object.entries(HTMLAttributes).forEach(([key, value]) => {
            if (value !== null && value !== undefined) {
              dom.setAttribute(key, String(value));
            }
          });
          return {
            dom,
            contentDOM: dom,
            update: updatedNode => {
              if (updatedNode.type.name !== node.type.name) {
                return false;
              }
              dom.style.height = `${updatedNode.attrs.height}px`;
              return true;
            },
            ignoreMutation: mutation =>
              mutation.type === 'attributes' &&
              mutation.attributeName === 'style' &&
              mutation.target === dom,
          };
        };
      },
    };
  },
});
