import type { Editor } from './../../../tiptap/core/index.js';
import type { Node as ProseMirrorNode } from './../../../tiptap/pm/model.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

import resizerStyles from '../../statics/styles/resizer-scss.js';
import { TableMap } from '../tablemap.js';
import { getStartColumnResizeDrag } from './column-resizing.js';
import { clearResizeTick, setResizeTick } from './resize-drag-controller.js';
import {
  clearResizeHoverActive,
  setColumnResizeHoverActive,
  setRowResizeHoverActive,
} from './resizing-plugin-keys.js';
import { getStartRowResizeDrag } from './row-resizing.js';
import { isSelectingCells } from './table-editing-plugin.js';

type ResizeHitZoneOverlayParams = {
  editor: Editor;
  node: ProseMirrorNode;
  getPos: () => number;
  columnHitZoneWidth: number;
  rowHitZoneHeight: number;
  viewport: HTMLElement;
  table: HTMLElement;
  colgroup: Element;
  contentDOM: HTMLElement;
  onResizeTick: () => void;
};

type ResizeHitZoneOwnerParams = {
  editor: Editor;
  getPos: () => number;
  dom: HTMLElement;
  getNode: () => ProseMirrorNode;
  hitZoneSize: number;
  clearOtherAxisHover: () => void;
  refreshOverlay: () => void;
};

type TableGeometry = {
  totalCols: number;
  totalRows: number;
  columnLefts: number[];
  columnWidths: number[];
  rowTops: number[];
  rowBottoms: number[];
  tableWidth: number;
  tableHeight: number;
  cellSpacing: number;
};

type ColumnSegment = {
  colIdx: number;
  top: number;
  bottom: number;
  center: number;
};
type RowSegment = {
  rowIdx: number;
  left: number;
  right: number;
  center: number;
};

type UnblockedRun = {
  start: number;
  end: number;
  blockedBefore: boolean;
  blockedAfter: boolean;
};

const removeResizeHoverClasses = (zone: HTMLElement): void => {
  zone.classList.remove(resizerStyles.peerHovered, resizerStyles.active);
};

const forEachUnblockedRun = (blocked: boolean[], visitRun: (run: UnblockedRun) => void): void => {
  let runStart = -1;
  for (let index = 0; index <= blocked.length; index++) {
    const isBlocked = index === blocked.length ? true : blocked[index];
    if (isBlocked) {
      if (runStart !== -1) {
        visitRun({
          start: runStart,
          end: index - 1,
          blockedBefore: runStart > 0 && blocked[runStart - 1],
          blockedAfter: index < blocked.length,
        });
        runStart = -1;
      }
    } else if (runStart === -1) {
      runStart = index;
    }
  }
};

const getColumnResizeSegments = (geometry: TableGeometry, map: TableMap): ColumnSegment[] => {
  const { totalCols, totalRows, columnLefts, columnWidths, rowTops, rowBottoms, cellSpacing } =
    geometry;
  const segments: ColumnSegment[] = [];
  const blockedRows: boolean[] = new Array(totalRows);

  for (let colIdx = 0; colIdx < totalCols; colIdx++) {
    const isLastCol = colIdx === totalCols - 1;
    for (let rowIdx = 0; rowIdx < totalRows; rowIdx++) {
      blockedRows[rowIdx] =
        !isLastCol &&
        map.map[rowIdx * totalCols + colIdx] === map.map[rowIdx * totalCols + colIdx + 1];
    }

    forEachUnblockedRun(blockedRows, ({ start, end, blockedBefore, blockedAfter }) => {
      const top = blockedBefore ? rowTops[start] + cellSpacing / 2 : rowTops[start];
      const bottom = blockedAfter ? rowBottoms[end] + cellSpacing / 2 : rowBottoms[end];
      const rightEdgeX = columnLefts[colIdx] + columnWidths[colIdx];
      const center = isLastCol ? rightEdgeX : rightEdgeX + cellSpacing / 2;
      segments.push({ colIdx, top, bottom, center });
    });
  }

  return segments;
};

const getRowResizeSegments = (geometry: TableGeometry, map: TableMap): RowSegment[] => {
  const { totalCols, totalRows, columnLefts, columnWidths, rowBottoms, cellSpacing } = geometry;
  const segments: RowSegment[] = [];
  const blockedCols: boolean[] = new Array(totalCols);

  for (let rowIdx = 0; rowIdx < totalRows; rowIdx++) {
    const isLastRow = rowIdx === totalRows - 1;
    for (let colIdx = 0; colIdx < totalCols; colIdx++) {
      blockedCols[colIdx] =
        !isLastRow &&
        map.map[rowIdx * totalCols + colIdx] === map.map[(rowIdx + 1) * totalCols + colIdx];
    }

    forEachUnblockedRun(blockedCols, ({ start, end, blockedBefore, blockedAfter }) => {
      const left = blockedBefore ? columnLefts[start] + cellSpacing / 2 : columnLefts[start];
      const right = blockedAfter
        ? columnLefts[end] + columnWidths[end] + cellSpacing / 2
        : columnLefts[end] + columnWidths[end];
      const bottomEdgeY = rowBottoms[rowIdx];
      const center = isLastRow ? bottomEdgeY : bottomEdgeY + cellSpacing / 2;
      segments.push({ rowIdx, left, right, center });
    });
  }

  return segments;
};

type BoundaryPeerHoverParams = {
  findBoundaryPeers: (zone: HTMLElement) => HTMLElement[];
  isAxisHovered: () => boolean;
  setHoverActive: (active: boolean) => void;
  clearOtherAxisHover: () => void;
};

const wireBoundaryPeerHover = (
  zone: HTMLElement,
  { findBoundaryPeers, isAxisHovered, setHoverActive, clearOtherAxisHover }: BoundaryPeerHoverParams
): void => {
  zone.addEventListener('pointerenter', () => {
    setHoverActive(true);
    clearOtherAxisHover();
    findBoundaryPeers(zone).forEach(s => s.classList.add(resizerStyles.peerHovered));
  });
  zone.addEventListener('pointerleave', () => {
    requestAnimationFrame(() => {
      const peers = findBoundaryPeers(zone);
      if (peers.some(s => s.matches(':hover'))) {
        return;
      }
      peers.forEach(s => s.classList.remove(resizerStyles.peerHovered));
      if (!isAxisHovered()) {
        setHoverActive(false);
      }
    });
  });
};

const markBoundaryActiveUntilPointerRelease = (
  view: EditorView,
  pointerId: number,
  zone: HTMLElement,
  findBoundaryPeers: (zone: HTMLElement) => HTMLElement[],
  refreshOverlay: () => void
): (() => void) => {
  const peers = findBoundaryPeers(zone);
  peers.forEach(peer => peer.classList.add(resizerStyles.active));
  setResizeTick(view, refreshOverlay);

  const clearActiveBoundary = () => {
    clearResizeHoverActive(view);
    peers.forEach(removeResizeHoverClasses);
    clearResizeTick(view, refreshOverlay);
    document.removeEventListener('pointerup', clear, true);
    document.removeEventListener('pointercancel', clear, true);
  };

  const clear = (event: PointerEvent) => {
    if (event.pointerId === pointerId) {
      clearActiveBoundary();
    }
  };
  document.addEventListener('pointerup', clear, true);
  document.addEventListener('pointercancel', clear, true);
  return clearActiveBoundary;
};

const resizeHitZoneArray = (
  zones: HTMLElement[],
  target: number,
  createZone: () => HTMLElement,
  removeZone: (zone: HTMLElement) => void
): void => {
  while (zones.length > target) {
    const zone = zones.pop();
    if (zone) {
      removeZone(zone);
      zone.remove();
    }
  }
  while (zones.length < target) {
    zones.push(createZone());
  }
};

class ColumnResizeHitZones {
  private readonly editor: Editor;

  private readonly getPos: () => number;

  private readonly dom: HTMLElement;

  private readonly getNode: () => ProseMirrorNode;

  private readonly hitZoneSize: number;

  private readonly clearOtherAxisHover: () => void;

  private readonly refreshOverlay: () => void;

  private zones: HTMLElement[] = [];

  constructor({
    editor,
    getPos,
    dom,
    getNode,
    hitZoneSize,
    clearOtherAxisHover,
    refreshOverlay,
  }: ResizeHitZoneOwnerParams) {
    this.editor = editor;
    this.getPos = getPos;
    this.dom = dom;
    this.getNode = getNode;
    this.hitZoneSize = hitZoneSize;
    this.clearOtherAxisHover = clearOtherAxisHover;
    this.refreshOverlay = refreshOverlay;
  }

  sync(geometry: TableGeometry, map: TableMap): void {
    const segments = getColumnResizeSegments(geometry, map);
    resizeHitZoneArray(
      this.zones,
      segments.length,
      () => this.createZone(),
      () => this.setHoverActive(false)
    );

    for (let index = 0; index < segments.length; index++) {
      this.positionZone(this.zones[index], segments[index], geometry);
    }
  }

  clearHover(): void {
    this.zones.forEach(removeResizeHoverClasses);
    this.setHoverActive(false);
  }

  private createZone(): HTMLElement {
    const zone = document.createElement('div');
    zone.className = resizerStyles.columnResizeHitZone;
    this.dom.appendChild(zone);
    zone.addEventListener('pointerdown', this.handlePointerDown);
    wireBoundaryPeerHover(zone, {
      findBoundaryPeers: this.findBoundaryPeers,
      isAxisHovered: this.isAxisHovered,
      setHoverActive: this.setHoverActive,
      clearOtherAxisHover: this.clearOtherAxisHover,
    });
    return zone;
  }

  private positionZone(zone: HTMLElement, segment: ColumnSegment, geometry: TableGeometry): void {
    const left = Math.min(
      Math.max(segment.center - this.hitZoneSize / 2, 0),
      Math.max(geometry.tableWidth - this.hitZoneSize, 0)
    );
    zone.style.left = `${left}px`;
    zone.style.top = `${segment.top}px`;
    zone.style.width = `${this.hitZoneSize}px`;
    zone.style.height = `${segment.bottom - segment.top}px`;
    zone.dataset.colIdx = String(segment.colIdx);
    zone.dataset.tableEdge = segment.colIdx === geometry.totalCols - 1 ? 'right' : '';
  }

  private findBoundaryPeers = (zone: HTMLElement): HTMLElement[] => {
    const overlay = zone.parentElement;
    const colIdx = zone.dataset.colIdx;
    if (!overlay || colIdx === undefined) {
      return [zone];
    }
    return Array.from(
      overlay.querySelectorAll<HTMLElement>(
        `.${resizerStyles.columnResizeHitZone}[data-col-idx="${colIdx}"]`
      )
    );
  };

  private isAxisHovered = (): boolean => {
    return this.zones.some(zone => zone.matches(':hover'));
  };

  private setHoverActive = (active: boolean): void => {
    setColumnResizeHoverActive(this.editor.view, active);
  };

  private handlePointerDown = (event: PointerEvent): void => {
    if (event.button !== 0 || isSelectingCells(this.editor.state) || !this.editor.isEditable) {
      return;
    }
    const target = event.currentTarget as HTMLElement;
    const colIdx = Number(target.dataset.colIdx);
    if (!Number.isFinite(colIdx)) {
      return;
    }

    const map = TableMap.get(this.getNode());
    const isLast = colIdx === map.width - 1;
    const tablePosition = this.getPos() + 1;
    this.setHoverActive(false);
    const clearActiveBoundary = markBoundaryActiveUntilPointerRelease(
      this.editor.view,
      event.pointerId,
      target,
      this.findBoundaryPeers,
      this.refreshOverlay
    );
    const startColumnResizeDrag = getStartColumnResizeDrag(this.editor);
    const didStart = startColumnResizeDrag?.(this.editor.view, {
      tablePosition,
      columnInfo: { index: colIdx },
      nextColumnInfo: isLast ? undefined : { index: colIdx + 1 },
      event,
    });
    if (!didStart) {
      clearActiveBoundary();
      return;
    }
  };
}

class RowResizeHitZones {
  private readonly editor: Editor;

  private readonly getPos: () => number;

  private readonly dom: HTMLElement;

  private readonly getNode: () => ProseMirrorNode;

  private readonly hitZoneSize: number;

  private readonly clearOtherAxisHover: () => void;

  private readonly refreshOverlay: () => void;

  private zones: HTMLElement[] = [];

  constructor({
    editor,
    getPos,
    dom,
    getNode,
    hitZoneSize,
    clearOtherAxisHover,
    refreshOverlay,
  }: ResizeHitZoneOwnerParams) {
    this.editor = editor;
    this.getPos = getPos;
    this.dom = dom;
    this.getNode = getNode;
    this.hitZoneSize = hitZoneSize;
    this.clearOtherAxisHover = clearOtherAxisHover;
    this.refreshOverlay = refreshOverlay;
  }

  sync(geometry: TableGeometry, map: TableMap): void {
    const segments = getRowResizeSegments(geometry, map);
    resizeHitZoneArray(
      this.zones,
      segments.length,
      () => this.createZone(),
      () => this.setHoverActive(false)
    );

    for (let index = 0; index < segments.length; index++) {
      this.positionZone(this.zones[index], segments[index], geometry);
    }
  }

  clearHover(): void {
    this.zones.forEach(removeResizeHoverClasses);
    this.setHoverActive(false);
  }

  private createZone(): HTMLElement {
    const zone = document.createElement('div');
    zone.className = resizerStyles.rowResizeHitZone;
    this.dom.appendChild(zone);
    zone.addEventListener('pointerdown', this.handlePointerDown);
    wireBoundaryPeerHover(zone, {
      findBoundaryPeers: this.findBoundaryPeers,
      isAxisHovered: this.isAxisHovered,
      setHoverActive: this.setHoverActive,
      clearOtherAxisHover: this.clearOtherAxisHover,
    });
    return zone;
  }

  private positionZone(zone: HTMLElement, segment: RowSegment, geometry: TableGeometry): void {
    const top = Math.min(
      Math.max(segment.center - this.hitZoneSize / 2, 0),
      Math.max(geometry.tableHeight - this.hitZoneSize, 0)
    );
    zone.style.top = `${top}px`;
    zone.style.left = `${segment.left}px`;
    zone.style.width = `${segment.right - segment.left}px`;
    zone.style.height = `${this.hitZoneSize}px`;
    zone.dataset.rowIdx = String(segment.rowIdx);
    zone.dataset.tableEdge = segment.rowIdx === geometry.totalRows - 1 ? 'bottom' : '';
  }

  private findBoundaryPeers = (zone: HTMLElement): HTMLElement[] => {
    const overlay = zone.parentElement;
    const rowIdx = zone.dataset.rowIdx;
    if (!overlay || rowIdx === undefined) {
      return [zone];
    }
    return Array.from(
      overlay.querySelectorAll<HTMLElement>(
        `.${resizerStyles.rowResizeHitZone}[data-row-idx="${rowIdx}"]`
      )
    );
  };

  private isAxisHovered = (): boolean => {
    return this.zones.some(zone => zone.matches(':hover'));
  };

  private setHoverActive = (active: boolean): void => {
    setRowResizeHoverActive(this.editor.view, active);
  };

  private handlePointerDown = (event: PointerEvent): void => {
    if (event.button !== 0 || isSelectingCells(this.editor.state) || !this.editor.isEditable) {
      return;
    }
    const target = event.currentTarget as HTMLElement;
    const rowIdx = Number(target.dataset.rowIdx);
    if (!Number.isFinite(rowIdx)) {
      return;
    }

    const node = this.getNode();
    const tablePosition = this.getPos() + 1;
    let rowPos: number | undefined;
    let nextRowPos: number | undefined;
    let currentRowIndex = 0;
    node.forEach((_node, offset) => {
      if (currentRowIndex === rowIdx) {
        rowPos = tablePosition + offset;
      }
      if (currentRowIndex === rowIdx + 1) {
        nextRowPos = tablePosition + offset;
      }
      currentRowIndex++;
    });

    if (rowPos === undefined) {
      return;
    }

    this.setHoverActive(false);
    const clearActiveBoundary = markBoundaryActiveUntilPointerRelease(
      this.editor.view,
      event.pointerId,
      target,
      this.findBoundaryPeers,
      this.refreshOverlay
    );
    const startRowResizeDrag = getStartRowResizeDrag(this.editor);
    const didStart = startRowResizeDrag?.(this.editor.view, {
      tablePosition,
      rowInfo: { position: rowPos, index: rowIdx },
      nextRowInfo:
        nextRowPos !== undefined ? { position: nextRowPos, index: rowIdx + 1 } : undefined,
      event,
    });
    if (!didStart) {
      clearActiveBoundary();
      return;
    }
  };
}

export class ResizeHitZoneOverlay {
  private node: ProseMirrorNode;

  private readonly editor: Editor;

  private readonly table: HTMLElement;

  private readonly colgroup: Element;

  private readonly contentDOM: HTMLElement;

  private readonly onResizeTick: () => void;

  readonly dom: HTMLElement;

  private readonly columnHitZones: ColumnResizeHitZones;

  private readonly rowHitZones: RowResizeHitZones;

  private pendingUpdateRaf = 0;

  private readonly refreshOverlay = (): void => {
    this.update();
    this.onResizeTick();
  };

  constructor({
    editor,
    node,
    getPos,
    columnHitZoneWidth,
    rowHitZoneHeight,
    viewport,
    table,
    colgroup,
    contentDOM,
    onResizeTick,
  }: ResizeHitZoneOverlayParams) {
    this.editor = editor;
    this.node = node;
    this.table = table;
    this.colgroup = colgroup;
    this.contentDOM = contentDOM;
    this.onResizeTick = onResizeTick;

    this.dom = document.createElement('div');
    this.dom.className = resizerStyles.resizeOverlay;
    this.dom.setAttribute('contenteditable', 'false');
    viewport.appendChild(this.dom);

    this.columnHitZones = new ColumnResizeHitZones({
      editor,
      getPos,
      dom: this.dom,
      getNode: () => this.node,
      hitZoneSize: columnHitZoneWidth,
      clearOtherAxisHover: () => this.rowHitZones.clearHover(),
      refreshOverlay: this.refreshOverlay,
    });
    this.rowHitZones = new RowResizeHitZones({
      editor,
      getPos,
      dom: this.dom,
      getNode: () => this.node,
      hitZoneSize: rowHitZoneHeight,
      clearOtherAxisHover: () => this.columnHitZones.clearHover(),
      refreshOverlay: this.refreshOverlay,
    });
  }

  setNode(node: ProseMirrorNode): void {
    this.node = node;
  }

  scheduleUpdate(): void {
    if (this.pendingUpdateRaf !== 0) {
      return;
    }
    this.pendingUpdateRaf = requestAnimationFrame(() => {
      this.pendingUpdateRaf = 0;
      this.update();
    });
  }

  destroy(): void {
    if (this.pendingUpdateRaf !== 0) {
      cancelAnimationFrame(this.pendingUpdateRaf);
      this.pendingUpdateRaf = 0;
    }
    clearResizeTick(this.editor.view, this.refreshOverlay);
    clearResizeHoverActive(this.editor.view);
  }

  private update(): void {
    if (!this.editor.isEditable) {
      this.hide();
      return;
    }

    const firstRow = this.contentDOM.firstElementChild as HTMLTableRowElement | null;
    const rows = this.contentDOM.querySelectorAll<HTMLTableRowElement>(':scope > tr');
    if (!firstRow || !rows.length) {
      this.hide();
      return;
    }

    const map = TableMap.get(this.node);
    if (map.width === 0 || map.height === 0) {
      this.hide();
      return;
    }

    const cellSpacing = (this.node.attrs.tableData?.cellSpacing as number | undefined) ?? 0;
    const tableWidth = this.table.offsetWidth;
    const tableHeight = this.table.offsetHeight;

    const geometry = this.getTableGeometry(rows, map, cellSpacing, tableWidth, tableHeight);
    if (!geometry) {
      this.hide();
      return;
    }

    this.dom.style.display = 'block';
    this.dom.style.left = `${this.table.offsetLeft}px`;
    this.dom.style.top = `${this.table.offsetTop}px`;
    this.dom.style.width = `${tableWidth}px`;
    this.dom.style.height = `${tableHeight}px`;

    this.columnHitZones.sync(geometry, map);
    this.rowHitZones.sync(geometry, map);
  }

  private hide(): void {
    this.dom.style.display = 'none';
    clearResizeHoverActive(this.editor.view);
  }

  private getTableGeometry(
    rows: NodeListOf<HTMLTableRowElement>,
    map: TableMap,
    cellSpacing: number,
    tableWidth: number,
    tableHeight: number
  ): TableGeometry | null {
    const totalCols = map.width;
    const totalRows = map.height;
    const columnGeometry = this.getColumnGeometry(totalCols);
    if (!columnGeometry) {
      return null;
    }

    const rowTops: number[] = new Array(totalRows);
    const rowBottoms: number[] = new Array(totalRows);
    for (let r = 0; r < totalRows; r++) {
      const row = rows[r];
      if (!row) {
        return null;
      }
      rowTops[r] = row.offsetTop;
      rowBottoms[r] = row.offsetTop + row.offsetHeight;
    }

    return {
      totalCols,
      totalRows,
      columnLefts: columnGeometry.lefts,
      columnWidths: columnGeometry.widths,
      rowTops,
      rowBottoms,
      tableWidth,
      tableHeight,
      cellSpacing,
    };
  }

  private getColumnGeometry(totalCols: number): { lefts: number[]; widths: number[] } | null {
    const cols = Array.from(this.colgroup.children).slice(0, totalCols);
    if (cols.length < totalCols) {
      return null;
    }

    const lefts: number[] = new Array(totalCols);
    const widths: number[] = new Array(totalCols);
    let left = 0;
    for (let i = 0; i < totalCols; i++) {
      const width = (cols[i] as HTMLElement).offsetWidth;
      if (!Number.isFinite(width)) {
        return null;
      }
      lefts[i] = left;
      widths[i] = width;
      left += width;
    }

    return { lefts, widths };
  }
}
