/* oxlint-disable fp/no-loops */

// This file defines a number of helpers for wiring up user input to
// table-related functionality.
import type { ResolvedPos } from './../../../tiptap/pm/model.js';
import { Fragment } from './../../../tiptap/pm/model.js';
import { Transform } from './../../../tiptap/pm/transform.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

import { cellAround, isInTable, selectionCell, tableNodeTypes } from '../commands/queries.js';
import { RicosCellSelection, getRectBetweenCells, inSameTable } from '../plugins/cellselection.js';
import { TableMap } from '../tablemap.js';
import { clipCells, insertCells, pastedCells } from '../utilities/copypaste.js';
import { isRicosCellSelection } from '../utilities/is-selection-type.js';

export function handlePaste(view: $TSFixMe, _: $TSFixMe, slice: $TSFixMe) {
  if (!isInTable(view.state)) {
    return false;
  }
  let cells = pastedCells(slice);
  const sel = view.state.selection;

  if (isRicosCellSelection(sel)) {
    if (!cells) {
      cells = {
        width: 1,
        height: 1,
        rows: [Fragment.from(fitSlice(tableNodeTypes(view.state.schema).cell, slice))],
      };
    }

    const start = sel.$anchorCell.start(-1);

    // Get the bounding rectangle for the selection
    // For both RicosCellSelection and standard CellSelection, get all cells
    const cellsArray: ResolvedPos[] = [];
    sel.forEachCell((_node: $TSFixMe, pos: number) => {
      cellsArray.push(view.state.doc.resolve(pos));
    });
    const rect = getRectBetweenCells(cellsArray);

    cells = clipCells(cells, rect.right - rect.left, rect.bottom - rect.top);
    insertCells(view.state, view.dispatch, start, rect, cells);
    return true;
  } else if (cells) {
    const $cell = selectionCell(view.state);
    if ($cell) {
      const start = $cell.start(-1);
      const { col, row, colspan, rowspan } = TableMap.get($cell.node(-1)).findCell(
        $cell.pos - start
      );
      insertCells(
        view.state,
        view.dispatch,
        start,
        { left: col, top: row, right: col + colspan, bottom: row + rowspan },
        cells
      );
      return true;
    }
  }
  return false;
}

export function handleMouseDown(
  view: $TSFixMe,
  startEvent: $TSFixMe,
  key: $TSFixMe,
  isMobile?: boolean
) {
  if (isMobile || startEvent.button !== 0) {
    return;
  }
  const startDOMCell = domInCell(view, startEvent.target);

  // Handle Ctrl/Cmd+click for toggling individual cells in multi-selection
  if ((startEvent.ctrlKey || startEvent.metaKey) && startDOMCell) {
    const $cell = cellUnderMouse(view, startEvent);
    if ($cell) {
      const newSelection = RicosCellSelection.toggleCell(
        view.state.selection,
        $cell.pos,
        view.state.doc
      );
      view.dispatch(view.state.tr.setSelection(newSelection));
      startEvent.preventDefault();
    }
    return;
  }

  let $anchor;

  if (startEvent.shiftKey && isRicosCellSelection(view.state.selection)) {
    // Adding to an existing cell selection
    setCellSelection(view.state.selection.$anchorCell, startEvent);
    startEvent.preventDefault();
  } else if (
    startEvent.shiftKey &&
    startDOMCell &&
    ($anchor = cellAround(view.state.selection.$anchor)) !== null &&
    cellUnderMouse(view, startEvent)?.pos !== $anchor.pos
  ) {
    // Adding to a selection that starts in another cell (causing a
    // cell selection to be created).
    setCellSelection($anchor, startEvent);
    startEvent.preventDefault();
    // oxlint-disable-next-line brace-style
  } else if (!startDOMCell) {
    // Not in a cell, let the default behavior happen.
    return;
  }

  // Don't interfere with text drag-and-drop: if mousedown is on already-selected
  // text, the user might be starting a drag operation
  const { selection } = view.state;
  if (!isRicosCellSelection(selection) && !selection.empty) {
    const clickPos = view.posAtCoords({ left: startEvent.clientX, top: startEvent.clientY });
    if (clickPos && clickPos.pos >= selection.from && clickPos.pos <= selection.to) {
      // Click is on selected text - don't set up cell selection, allow drag-and-drop
      return;
    }
  }

  // Capture pointer to prevent drag behavior during cell selection
  const pointerId = startEvent.pointerId;
  const captureTarget = startEvent.target as Element;
  if (pointerId !== undefined && captureTarget?.setPointerCapture) {
    captureTarget.setPointerCapture(pointerId);
  }

  function isSameCellSelection($anchor: ResolvedPos, $head: ResolvedPos): boolean {
    const { selection } = view.state;

    if (!isRicosCellSelection(selection)) {
      return false;
    }

    return selection.$anchorCell.pos === $anchor.pos && selection.$headCell.pos === $head.pos;
  }

  // Create and dispatch a cell selection between the given anchor and
  // the position under the mouse.
  function setCellSelection($anchor: ResolvedPos, event: $TSFixMe) {
    // Remove text selection which might get briefly introduced by pointermove
    const textSelection = view.root.getSelection?.();
    if (textSelection) {
      textSelection.removeAllRanges();
    }

    let $head = cellUnderMouse(view, event);
    const starting = key.getState(view.state) === null || key.getState(view.state) === undefined;

    if (!$head || !inSameTable($anchor, $head)) {
      if (starting) {
        $head = $anchor;
      } else {
        return;
      }
    }

    if (isSameCellSelection($anchor, $head!)) {
      return;
    }

    // Use getRectBetweenCells to get the bounding rectangle
    // This properly handles rowspan/colspan
    const rect = getRectBetweenCells([$anchor, $head!]);

    // Get all cells in the rectangle
    const table = $anchor.node(-1);
    const tableStart = $anchor.start(-1);
    const map = TableMap.get(table);
    const cellPositions = map.cellsInRect(rect);
    const cells = cellPositions.map(pos => view.state.doc.resolve(tableStart + pos));

    const selection = new RicosCellSelection(cells, view.state.doc);

    if (starting || !view.state.selection.eq(selection)) {
      const tr = view.state.tr.setSelection(selection);
      if (starting) {
        tr.setMeta(key, $anchor.pos);
      }
      view.dispatch(tr);
    }
  }

  let lastHeadDOMCell: HTMLElement | null = null;

  // Stop listening to pointer events.
  function stop() {
    view.root.removeEventListener('pointerup', stop);
    view.root.removeEventListener('pointermove', move);
    // Release pointer capture
    if (pointerId !== undefined && captureTarget?.releasePointerCapture) {
      try {
        captureTarget.releasePointerCapture(pointerId);
      } catch {
        // Pointer may have already been released
      }
    }
    lastHeadDOMCell = null;
    if (key.getState(view.state)) {
      // Clear the selecting state and trigger toolbar re-render
      view.dispatch(view.state.tr.setMeta(key, -1).setMeta('forceToolbarUpdate', true));
    }
  }

  function move(event: $TSFixMe) {
    // Use elementFromPoint instead of event.target because some platforms
    // don't update event.target during pointer capture or when there's an overlay
    const elementUnderPointer =
      document.elementFromPoint(event.clientX, event.clientY) || event.target;
    const currentDOMCell = domInCell(view, elementUnderPointer);
    if (currentDOMCell === lastHeadDOMCell) {
      return; // Still in the same cell, no need to update selection
    }

    const anchor = key.getState(view.state);
    let $anchor;
    if (anchor !== null) {
      // Continuing an existing cross-cell selection
      $anchor = view.state.doc.resolve(anchor);
    } else if (currentDOMCell !== startDOMCell) {
      // Moving out of the initial cell -- start a new cell selection
      $anchor = cellUnderMouse(view, startEvent);
      if (!$anchor) {
        return stop();
      }
    }
    if ($anchor) {
      setCellSelection($anchor, event);
      lastHeadDOMCell = currentDOMCell;
    }
  }

  view.root.addEventListener('pointerup', stop);
  view.root.addEventListener('pointermove', move);
}

function domInCell(view: $TSFixMe, dom: $TSFixMe) {
  // oxlint-disable-next-line no-param-reassign
  for (; dom && dom !== view.dom; dom = dom.parentNode) {
    if (dom.nodeName === 'TD' || dom.nodeName === 'TH') {
      return dom;
    }
  }
}

function cellUnderMouse(view: EditorView, event: $TSFixMe) {
  // Use elementFromPoint instead of event.target because some platforms
  // don't update event.target during pointer capture or when there's an overlay
  const elementUnderPointer =
    document.elementFromPoint(event.clientX, event.clientY) || event.target;
  const cell = domInCell(view, elementUnderPointer);

  if (!cell) {
    return null;
  }

  return view.state.doc.resolve(view.posAtDOM(cell, 0) - 1);
}

function fitSlice(nodeType: $TSFixMe, slice: $TSFixMe) {
  const node = nodeType.createAndFill();
  const tr = new Transform(node).replace(0, node.content.size, slice);
  return tr.doc;
}
