import type { EditorState, Transaction } from 'prosemirror-state';
import { TextSelection } from 'prosemirror-state';

import type { Node as ProseMirrorNode } from './../../../tiptap/pm/model.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

import { RicosCellSelection, getCellsInExpandedRect } from '../plugins/cellselection.js';
import { TableQuery } from '../table-query.js';
import { TableMap } from '../tablemap.js';
import { isRicosCellSelection } from '../utilities/is-selection-type.js';
import { columnIsHeader, rowIsHeader, selectedRect, tableNodeTypes } from './queries.js';

// ---------------------------------------------------------------------------
// Transaction-level selection helpers (work on an existing tr, no dispatch)
// ---------------------------------------------------------------------------

function selectColumnsTr(tr: Transaction, fromCol: number, toCol: number, tablePos: number): void {
  const $tablePos = tr.doc.resolve(tablePos);
  const tempSelection = TextSelection.create(tr.doc, $tablePos.pos);
  const table = TableQuery.of(tempSelection);
  if (!table) {
    return;
  }
  const initialRect = { left: fromCol, right: toCol + 1, top: 0, bottom: table.map.height };
  const cells = getCellsInExpandedRect(tr.doc, table.getStartPos(), table.map, initialRect);
  const selection = new RicosCellSelection(cells, tr.doc);
  tr.setSelection(selection);
}

function selectRowsTr(tr: Transaction, fromRow: number, toRow: number, tablePos: number): void {
  const $tablePos = tr.doc.resolve(tablePos);
  const tempSelection = TextSelection.create(tr.doc, $tablePos.pos);
  const table = TableQuery.of(tempSelection);
  if (!table) {
    return;
  }
  const initialRect = { left: 0, right: table.map.width, top: fromRow, bottom: toRow + 1 };
  const cells = getCellsInExpandedRect(tr.doc, table.getStartPos(), table.map, initialRect);
  const selection = new RicosCellSelection(cells, tr.doc);
  tr.setSelection(selection);
}

// ---------------------------------------------------------------------------
// Transaction-level reorder helpers (mutate tr, do NOT dispatch)
// ---------------------------------------------------------------------------

/**
 * Reorder rows on an existing transaction. Moves rows in range [from.start, from.end]
 * to the position before row `to`. Does NOT dispatch.
 */
export function reorderRowsTr(
  tr: Transaction,
  state: EditorState,
  from: { start: number; end: number },
  to: number
): void {
  const table = TableQuery.of(state.selection);
  if (!table) {
    return;
  }

  const tableStart = table.getStartPos();
  const tableNode = table.getNode();
  const hadHeaderRow = rowIsHeader(table.map, tableNode, 0);
  const hadHeaderCol = hadHeaderRow && columnIsHeader(table.map, tableNode, 0);
  const draggedRows: ProseMirrorNode[] = [];
  const rowsToDelete: { pos: number; node: ProseMirrorNode }[] = [];

  tableNode.forEach((row, offset, index) => {
    if (index >= from.start && index <= from.end) {
      draggedRows.push(row);
      rowsToDelete.push({
        pos: tableStart + offset,
        node: row,
      });
    }
  });

  let rowPos = tableStart;
  for (let i = 0; i < to; i++) {
    rowPos += tableNode.child(i).nodeSize;
  }

  // Insert rows at new position
  tr.insert(rowPos, draggedRows);

  // Delete original rows (from bottom to top to maintain positions)
  rowsToDelete
    .sort((a, b) => b.pos - a.pos)
    .forEach(({ pos, node }) => {
      const mappedPos = tr.mapping.map(pos);
      tr.delete(mappedPos, mappedPos + node.nodeSize);
    });

  // Header cells travel with their row — pin header types to row 0
  if (hadHeaderRow) {
    const tablePos = tr.mapping.map(tableStart - 1);
    const newTable = tr.doc.nodeAt(tablePos)!;
    const types = tableNodeTypes(newTable.type.schema);
    const newMap = TableMap.get(newTable);
    newMap.forEachCell((cellPos, placement) => {
      const cell = newTable.nodeAt(cellPos)!;
      const shouldBeHeader = placement.row === 0 || (hadHeaderCol && placement.col === 0);
      const expected = shouldBeHeader ? types.header_cell : types.cell;
      if (cell.type !== expected) {
        tr.setNodeMarkup(tablePos + 1 + cellPos, expected, cell.attrs);
      }
    });
  }
}

/**
 * Reorder columns on an existing transaction. Moves columns in range
 * [from.start, from.end] to the position before column `to`. Does NOT dispatch.
 */
export function reorderColumnsTr(
  tr: Transaction,
  state: EditorState,
  from: { start: number; end: number },
  to: number
): void {
  const table = TableQuery.of(state.selection);
  if (!table) {
    return;
  }

  const tableStart = table.getStartPos();
  const tableNode = table.getNode();
  const map = table.map;
  const hadHeaderCol = columnIsHeader(map, tableNode, 0);
  const hadHeaderRow = hadHeaderCol && rowIsHeader(map, tableNode, 0);

  // Expand selection to include cells with colspan that intersect the range
  let expandedStart = from.start;
  let expandedEnd = from.end;

  for (let row = 0; row < map.height; row++) {
    for (let col = from.start; col <= from.end; col++) {
      const cellPos = map.map[row * map.width + col];
      const placement = map.findCell(cellPos);
      if (placement.col < expandedStart) {
        expandedStart = placement.col;
      }
      if (placement.col + placement.colspan - 1 > expandedEnd) {
        expandedEnd = placement.col + placement.colspan - 1;
      }
    }
  }

  const dimensions = tableNode.attrs.dimensions;
  if (dimensions?.colsWidthRatio?.length > 0) {
    const colsWidthRatio = [...dimensions.colsWidthRatio];
    const colsMinWidth = dimensions.colsMinWidth ? [...dimensions.colsMinWidth] : [];

    const numColsToMove = expandedEnd - expandedStart + 1;
    const movedWidthRatios = colsWidthRatio.splice(expandedStart, numColsToMove);
    const movedMinWidths = colsMinWidth.splice(expandedStart, numColsToMove);

    const insertIndex = to > expandedStart ? to - numColsToMove : to;

    // Insert at new position
    colsWidthRatio.splice(insertIndex, 0, ...movedWidthRatios);
    if (colsMinWidth.length > 0) {
      colsMinWidth.splice(insertIndex, 0, ...movedMinWidths);
    }

    const newDimensions = {
      ...dimensions,
      colsWidthRatio,
      colsMinWidth: colsMinWidth.length > 0 ? colsMinWidth : dimensions.colsMinWidth,
    };

    tr.setNodeMarkup(tableStart - 1, null, {
      ...tableNode.attrs,
      dimensions: newDimensions,
    });
  }

  // Track cells to delete after insertion
  type CellToDelete = { pos: number; node: ProseMirrorNode };
  const cellsToDelete: CellToDelete[] = [];

  tableNode.forEach((row, rowOffset, rowIndex) => {
    const cellsToInsert: ProseMirrorNode[] = [];

    // Collect cells that span the expanded selected columns
    for (let col = expandedStart; col <= expandedEnd; col++) {
      const mapPos = map.map[rowIndex * map.width + col];
      const placement = map.findCell(mapPos);

      // Only process if this is the cell's starting column AND starting row
      // This avoids processing cells with rowspan multiple times
      if (placement.col === col && placement.row === rowIndex) {
        const cellNode = tableNode.nodeAt(mapPos);
        if (cellNode) {
          cellsToInsert.push(cellNode);
          // Track for deletion
          const cellPosInTable = mapPos;
          cellsToDelete.push({
            pos: tableStart + cellPosInTable,
            node: cellNode,
          });
        }
      }
    }

    // Insert cells at target position
    if (cellsToInsert.length > 0) {
      const dropPosRel = map.positionAt(rowIndex, to, tableNode);
      const insertPos = tr.mapping.map(tableStart + dropPosRel);
      tr.insert(insertPos, cellsToInsert);
    }
  });

  // Delete original cells (from bottom to top to maintain positions)
  cellsToDelete
    .sort((a, b) => b.pos - a.pos)
    .forEach(({ pos, node }) => {
      const mappedPos = tr.mapping.map(pos);
      tr.delete(mappedPos, mappedPos + node.nodeSize);
    });

  // Header cells travel with their column — pin header types to col 0
  if (hadHeaderCol) {
    const tablePos = tr.mapping.map(tableStart - 1);
    const newTable = tr.doc.nodeAt(tablePos)!;
    const types = tableNodeTypes(newTable.type.schema);
    const newMap = TableMap.get(newTable);
    newMap.forEachCell((cellPos, placement) => {
      const cell = newTable.nodeAt(cellPos)!;
      const shouldBeHeader = placement.col === 0 || (hadHeaderRow && placement.row === 0);
      const expected = shouldBeHeader ? types.header_cell : types.cell;
      if (cell.type !== expected) {
        tr.setNodeMarkup(tablePos + 1 + cellPos, expected, cell.attrs);
      }
    });
  }
}

// ---------------------------------------------------------------------------
// Pure ProseMirror commands
// ---------------------------------------------------------------------------

/**
 * Reorder rows: move rows [from.start..from.end] before row `to`.
 */
export const reorderRows =
  (from: { start: number; end: number }, to: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const table = TableQuery.of(state.selection);
    if (!table) {
      return false;
    }
    if (!dispatch) {
      return true;
    }
    const tr = state.tr;
    reorderRowsTr(tr, state, from, to);
    dispatch(tr);
    return true;
  };

/**
 * Reorder columns: move columns [from.start..from.end] before column `to`.
 */
export const reorderColumns =
  (from: { start: number; end: number }, to: number) =>
  (state: EditorState, dispatch?: (tr: Transaction) => void): boolean => {
    const table = TableQuery.of(state.selection);
    if (!table) {
      return false;
    }
    if (!dispatch) {
      return true;
    }
    const tr = state.tr;
    reorderColumnsTr(tr, state, from, to);
    dispatch(tr);
    return true;
  };

/**
 * Move the currently selected full columns left or right.
 * Composes reorder + selection on a single transaction.
 */
export const moveColumns =
  (direction: 'left' | 'right') =>
  (state: EditorState, dispatch?: (tr: Transaction) => void, view?: EditorView): boolean => {
    const table = TableQuery.of(state.selection);
    if (!table || !isRicosCellSelection(state.selection)) {
      return false;
    }

    const rect = isRicosCellSelection(state.selection)
      ? state.selection.getRect()
      : selectedRect(state);

    // Only allow moving when full columns are selected
    if (rect.top !== 0 || rect.bottom !== table.getHeight()) {
      return false;
    }

    const firstCol = rect.left;
    const lastCol = rect.right - 1;
    const colWidth = rect.right - rect.left;
    const targetCol = direction === 'left' ? firstCol - 1 : lastCol + 1;
    const tableStart = table.getStartPos();

    if (targetCol < 0 || targetCol > table.getWidth()) {
      return false;
    }

    let newTargetCol = targetCol;

    // Account for colspan of the target column (skip edges where map index would wrap)
    if (targetCol > 0 && targetCol < table.map.width) {
      const cellColStartPos = targetCol;
      // last row, last column
      const cellColEndPos = table.map.width * (table.map.height - 1) + cellColStartPos;
      // Check cells in the target column across all rows to find spans
      const targetRect = table.map.rectBetween(
        table.map.map[cellColStartPos],
        table.map.map[cellColEndPos]
      );

      newTargetCol = direction === 'left' ? targetRect.left : targetRect.right;
    }

    // Calculate final position after reordering
    // When moving LEFT: columns inserted at newTargetCol, original columns deleted after -> stay at newTargetCol
    // When moving RIGHT: columns inserted at newTargetCol, original columns deleted before -> shift to newTargetCol - colWidth
    const finalColStart = direction === 'left' ? newTargetCol : newTargetCol - colWidth;
    const finalColEnd = finalColStart + colWidth - 1;

    if (!dispatch) {
      return true;
    }

    const tr = state.tr;
    reorderColumnsTr(tr, state, { start: firstCol, end: lastCol }, newTargetCol);
    selectColumnsTr(tr, finalColStart, finalColEnd, tableStart);
    dispatch(tr);
    view?.focus();
    return true;
  };

/**
 * Move the currently selected full rows up or down.
 * Composes reorder + selection on a single transaction.
 */
export const moveRows =
  (direction: 'up' | 'down') =>
  (state: EditorState, dispatch?: (tr: Transaction) => void, view?: EditorView): boolean => {
    const table = TableQuery.of(state.selection);
    if (!table || !isRicosCellSelection(state.selection)) {
      return false;
    }

    const rect = isRicosCellSelection(state.selection)
      ? state.selection.getRect()
      : selectedRect(state);

    if (rect.left !== 0 || rect.right !== table.getWidth()) {
      return false;
    } // Must be full rows

    const firstRow = rect.top;
    const lastRow = rect.bottom - 1;
    const targetRow = direction === 'up' ? firstRow - 1 : lastRow + 1;
    const rowHeight = rect.bottom - rect.top;
    const tableStart = table.getStartPos();

    if (targetRow < 0 || targetRow > table.getHeight()) {
      return false;
    }

    let newTargetRow = targetRow;

    // Account for rowspan/colspan of the target row
    if (targetRow < table.map.height) {
      const toRowStart = targetRow * table.map.width;
      const toRowEnd = toRowStart + table.map.width - 1;
      const toRect = table.map.rectBetween(table.map.map[toRowStart], table.map.map[toRowEnd]);

      newTargetRow = direction === 'up' ? toRect.top : toRect.bottom;
    }

    // Calculate final position after reordering
    // When moving UP: rows inserted at newTargetRow, original rows deleted after -> stay at newTargetRow
    // When moving DOWN: rows inserted at newTargetRow, original rows deleted before -> shift to newTargetRow - rowHeight
    const finalRowStart = direction === 'up' ? newTargetRow : newTargetRow - rowHeight;
    const finalRowEnd = finalRowStart + rowHeight - 1;

    if (!dispatch) {
      return true;
    }

    const tr = state.tr;
    reorderRowsTr(tr, state, { start: firstRow, end: lastRow }, newTargetRow);
    selectRowsTr(tr, finalRowStart, finalRowEnd, tableStart);
    dispatch(tr);
    view?.focus();
    return true;
  };
