import { getElementScale } from './../../../_shared/get-element-scale.js';
import type { Editor } from './../../../tiptap/core/index.js';
import type { Node as ProseMirrorNode } from './../../../tiptap/pm/model.js';
import type { Transaction } from './../../../tiptap/pm/state.js';
import type { EditorView } from './../../../tiptap/pm/view.js';

import { getMinColumnWidthForPadding } from '../../defaults.js';
import { TableMap } from '../tablemap.js';
import { createResizeDragController, triggerResizeTick } from './resize-drag-controller.js';
import { getTableElement } from './resize-utils.js';
import {
  columnResizingPluginKey,
  isRowResizingActive,
  setColumnResizeDragActive,
} from './resizing-plugin-keys.js';
import type {
  ColumnResizingColumnInfo,
  ColumnResizingDragInfo,
  ColumnResizingDragState,
} from './types.js';

export { columnResizingPluginKey };

const DEFAULT_MIN_COLUMN_WIDTH = 25;
const COLUMN_WIDTH_EQUALITY_TOLERANCE = 0.5;

type StartArgs = {
  tablePosition: number;
  columnInfo: ColumnResizingColumnInfo;
  nextColumnInfo: ColumnResizingColumnInfo | undefined;
  event: PointerEvent;
};

const startColumnResizeDragByEditor = new WeakMap<
  Editor,
  (view: EditorView, args: StartArgs) => boolean
>();

export const getStartColumnResizeDrag = (editor: Editor) =>
  startColumnResizeDragByEditor.get(editor);

export const columnResizingPlugin = ({
  editor,
  minColumnWidth = DEFAULT_MIN_COLUMN_WIDTH,
}: {
  editor: Editor;
  minColumnWidth?: number;
}) => {
  let dragColElements: HTMLElement[] = [];
  let dragTableElement: HTMLElement | null = null;
  let dragSpacing = 0;
  let dragOriginalColWidths: string[] = [];
  let dragOriginalTableWidth = '';
  let dragOriginalTableMinWidth = '';
  let latestColumnNewWidth = 0;
  let latestNextColumnNewWidth: number | undefined = undefined;

  const clearDragDomSnapshot = (): void => {
    dragOriginalColWidths = [];
    dragOriginalTableWidth = '';
    dragOriginalTableMinWidth = '';
  };

  const restoreDragDom = (tableElement: HTMLElement | null, colElements: HTMLElement[]): void => {
    colElements.forEach((col, index) => {
      col.style.width = dragOriginalColWidths[index] ?? '';
    });
    if (tableElement) {
      tableElement.style.width = dragOriginalTableWidth;
      tableElement.style.minWidth = dragOriginalTableMinWidth;
    }
    clearDragDomSnapshot();
  };

  const controller = createResizeDragController<StartArgs, ColumnResizingDragState>(editor, {
    pluginKey: columnResizingPluginKey,
    setActive: setColumnResizeDragActive,
    isOtherActive: isRowResizingActive,

    begin(view, { tablePosition, columnInfo, nextColumnInfo, event }) {
      const colgroup = getColgroup(view, tablePosition);
      if (!colgroup) {
        return null;
      }
      const cols = Array.from(colgroup.querySelectorAll<HTMLElement>('col'));
      const table = view.state.doc.nodeAt(tablePosition - 1);
      if (!table) {
        return null;
      }
      const map = TableMap.get(table);
      const spacing = (table.attrs.tableData?.cellSpacing as number | undefined) ?? 0;

      const tableElement = getTableElement(view, tablePosition);
      if (!tableElement) {
        return null;
      }
      const minTableWidth = getTableMinimumWidth(tableElement);

      dragOriginalColWidths = cols.map(col => col.style.width);
      dragOriginalTableWidth = tableElement.style.width;
      dragOriginalTableMinWidth = tableElement.style.minWidth;

      const allColumnWidths: number[] = [];
      for (let i = 0; i < cols.length && i < map.width; i++) {
        const col = cols[i];
        if (!col.style.width) {
          col.style.width = `${col.offsetWidth}px`;
        }
        const baseWidth = i > 0 && spacing > 0 ? col.offsetWidth - spacing : col.offsetWidth;
        allColumnWidths.push(baseWidth);
      }

      const paddingAwareMinWidth = getMinColumnWidthForPadding(table.attrs?.tableData?.cellPadding);
      const effectiveMinWidth = Math.max(minColumnWidth, paddingAwareMinWidth);
      const dragColumnInfo = getDragColumnInfo(cols, columnInfo, effectiveMinWidth);
      const dragNextColumnInfo = nextColumnInfo
        ? getDragColumnInfo(cols, nextColumnInfo, effectiveMinWidth)
        : undefined;
      const maxRedistributedColumnWidth = getMaxRedistributedColumnWidth(
        dragColumnInfo,
        dragNextColumnInfo,
        spacing
      );

      dragColElements = cols;
      dragTableElement = tableElement;
      dragSpacing = spacing;
      latestColumnNewWidth = dragColumnInfo.newWidth;
      latestNextColumnNewWidth = dragNextColumnInfo?.newWidth;

      tableElement.style.width = `${Math.max(
        getTotalTableWidth({
          allColumnWidths,
          draggedColumnIndex: columnInfo.index,
          nextColumnIndex: nextColumnInfo?.index,
          newColWidth: dragColumnInfo.newWidth,
          newNextWidth: dragNextColumnInfo?.newWidth,
          spacing,
        }),
        minTableWidth
      )}px`;
      tableElement.style.minWidth = `${minTableWidth}px`;

      return {
        columnInfo: dragColumnInfo,
        initialTotalWidth: dragColumnInfo.newWidth + (dragNextColumnInfo?.newWidth ?? 0),
        initialColumnWidth: dragColumnInfo.newWidth,
        allColumnWidths,
        minTableWidth,
        maxRedistributedColumnWidth,
        nextColumnInfo: dragNextColumnInfo,
        tablePosition,
        scale: getElementScale(tableElement),
        startX: event.clientX,
      };
    },

    applyFrame(view, event, dragState) {
      if (dragColElements.length === 0) {
        return;
      }

      const scaledClientX = event.clientX / dragState.scale.scaleX;
      const scaledStartX = dragState.startX / dragState.scale.scaleX;
      const offset = scaledClientX - scaledStartX;
      const effectiveMinWidth = getEffectiveColumnMinWidth(dragState.columnInfo, dragSpacing);
      const requestedColWidth = Math.max(
        dragState.initialColumnWidth + offset,
        effectiveMinWidth,
        getMinDraggedColumnWidthForTable(dragState, dragSpacing)
      );
      const newColWidth =
        dragState.maxRedistributedColumnWidth === undefined
          ? requestedColWidth
          : Math.min(requestedColWidth, dragState.maxRedistributedColumnWidth);

      const nextColPotentialWidth = dragState.initialTotalWidth - newColWidth;
      const effectiveNextMinWidth = dragState.nextColumnInfo
        ? getEffectiveColumnMinWidth(dragState.nextColumnInfo, dragSpacing)
        : undefined;
      const newNextWidth =
        dragState.nextColumnInfo && effectiveNextMinWidth
          ? Math.max(nextColPotentialWidth, effectiveNextMinWidth)
          : undefined;

      latestColumnNewWidth = newColWidth;
      latestNextColumnNewWidth = newNextWidth;

      const draggedCol = dragColElements[dragState.columnInfo.index];
      if (draggedCol) {
        draggedCol.style.width = `${newColWidth}px`;
      }
      if (dragState.nextColumnInfo && newNextWidth !== undefined) {
        const nextCol = dragColElements[dragState.nextColumnInfo.index];
        if (nextCol) {
          nextCol.style.width = `${newNextWidth}px`;
        }
      }

      if (dragTableElement) {
        dragTableElement.style.width = `${Math.max(
          getTotalTableWidth({
            allColumnWidths: dragState.allColumnWidths,
            draggedColumnIndex: dragState.columnInfo.index,
            nextColumnIndex: dragState.nextColumnInfo?.index,
            newColWidth,
            newNextWidth,
            spacing: dragSpacing,
          }),
          dragState.minTableWidth
        )}px`;
      }

      triggerResizeTick(view);
      event.preventDefault();
      event.stopPropagation();
    },

    commit(view, dragState) {
      const finalColumnNewWidth = latestColumnNewWidth;
      const finalNextColumnNewWidth = latestNextColumnNewWidth;
      const tableElement = dragTableElement;
      const colElements = dragColElements;
      const table = view.state.doc.nodeAt(dragState.tablePosition - 1);
      dragColElements = [];
      dragTableElement = null;
      if (!table) {
        restoreDragDom(tableElement, colElements);
        return;
      }
      const map = TableMap.get(table);
      const start = dragState.tablePosition;
      const spacing = (table.attrs.tableData?.cellSpacing as number | undefined) ?? 0;
      const colsWidthRatio = getColumnWidthsForCommit({
        dragState,
        finalColumnNewWidth,
        finalNextColumnNewWidth,
        spacing,
      });
      if (areColumnWidthsEqual(colsWidthRatio, dragState.allColumnWidths)) {
        restoreDragDom(tableElement, colElements);
        return;
      }

      const tr = view.state.tr.setMeta('pointer', true);
      const writeColumnWidthAttr = (colIndex: number) => {
        const baseWidth = colsWidthRatio[colIndex];
        const width = colIndex > 0 && spacing > 0 ? baseWidth + spacing : baseWidth;
        setColumnWidth({ table, map, start, colIndex, width, tr });
      };
      writeColumnWidthAttr(dragState.columnInfo.index);
      if (dragState.nextColumnInfo) {
        writeColumnWidthAttr(dragState.nextColumnInfo.index);
      }

      tr.setNodeAttribute(dragState.tablePosition - 1, 'dimensions', {
        ...table.attrs.dimensions,
        colsWidthRatio,
        colsMinWidth: colsWidthRatio.map(width => Math.min(width, 120)),
      });

      view.dispatch(tr);
      clearDragDomSnapshot();
    },
  });

  startColumnResizeDragByEditor.set(editor, controller.start);
  return controller.plugin;
};

const getDragColumnInfo = (
  cols: HTMLElement[],
  { index }: ColumnResizingColumnInfo,
  minColumnWidth: number
): ColumnResizingDragInfo => {
  const currentWidth = cols[index] ? cols[index].offsetWidth : minColumnWidth;
  return { index, newWidth: currentWidth, minWidth: minColumnWidth };
};

const getMaxRedistributedColumnWidth = (
  columnInfo: ColumnResizingDragInfo,
  nextColumnInfo: ColumnResizingDragInfo | undefined,
  spacing: number
): number | undefined => {
  if (!nextColumnInfo) {
    return undefined;
  }

  const effectiveNextMinWidth = getEffectiveColumnMinWidth(nextColumnInfo, spacing);
  const nextColumnHasRedistributableSpace =
    nextColumnInfo.newWidth - effectiveNextMinWidth > COLUMN_WIDTH_EQUALITY_TOLERANCE;

  if (!nextColumnHasRedistributableSpace) {
    return undefined;
  }

  return columnInfo.newWidth + (nextColumnInfo.newWidth - effectiveNextMinWidth);
};

const getTableMinimumWidth = (tableElement: HTMLElement): number => {
  const container = tableElement.parentElement;
  if (!(container instanceof HTMLElement)) {
    return tableElement.offsetWidth;
  }

  const containerStyles = window.getComputedStyle(container);
  const horizontalPadding =
    parseFloat(containerStyles.paddingLeft || '0') +
    parseFloat(containerStyles.paddingRight || '0');

  return Math.max(container.clientWidth - horizontalPadding, 0);
};

const getMinDraggedColumnWidthForTable = (
  dragState: ColumnResizingDragState,
  spacing: number
): number => {
  if (dragState.nextColumnInfo || dragState.minTableWidth <= 0) {
    return 0;
  }

  const otherColumnsWidth = dragState.allColumnWidths.reduce((total, width, index) => {
    if (index === dragState.columnInfo.index) {
      return total;
    }
    return total + getRenderedColumnWidth(width, index, spacing);
  }, 0);

  return Math.max(dragState.minTableWidth - otherColumnsWidth, 0);
};

const getEffectiveColumnMinWidth = (columnInfo: ColumnResizingDragInfo, spacing: number): number =>
  columnInfo.index > 0 && spacing > 0 ? columnInfo.minWidth + spacing : columnInfo.minWidth;

const areColumnWidthsEqual = (widths: number[], nextWidths: number[]): boolean => {
  if (widths.length !== nextWidths.length) {
    return false;
  }
  return widths.every(
    (width, index) => Math.abs(width - nextWidths[index]) < COLUMN_WIDTH_EQUALITY_TOLERANCE
  );
};

function getColgroup(view: EditorView, tablePosition: number): Element | null {
  const tableElement = getTableElement(view, tablePosition);
  return tableElement ? tableElement.querySelector('colgroup') : null;
}

const getTotalTableWidth = ({
  allColumnWidths,
  draggedColumnIndex,
  nextColumnIndex,
  newColWidth,
  newNextWidth,
  spacing,
}: {
  allColumnWidths: number[];
  draggedColumnIndex: number;
  nextColumnIndex: number | undefined;
  newColWidth: number;
  newNextWidth: number | undefined;
  spacing: number;
}): number => {
  let totalWidth = 0;
  for (let index = 0; index < allColumnWidths.length; index++) {
    if (index === draggedColumnIndex) {
      totalWidth += newColWidth;
    } else if (index === nextColumnIndex && newNextWidth !== undefined) {
      totalWidth += newNextWidth;
    } else {
      const baseWidth = allColumnWidths[index];
      totalWidth += getRenderedColumnWidth(baseWidth, index, spacing);
    }
  }
  return totalWidth;
};

const getRenderedColumnWidth = (baseWidth: number, index: number, spacing: number): number =>
  index > 0 && spacing > 0 ? baseWidth + spacing : baseWidth;

const getColumnWidthsForCommit = ({
  dragState,
  finalColumnNewWidth,
  finalNextColumnNewWidth,
  spacing,
}: {
  dragState: ColumnResizingDragState;
  finalColumnNewWidth: number;
  finalNextColumnNewWidth: number | undefined;
  spacing: number;
}): number[] => {
  return dragState.allColumnWidths.map((baseWidth, colIndex) => {
    if (colIndex === dragState.columnInfo.index) {
      return colIndex > 0 && spacing > 0 ? finalColumnNewWidth - spacing : finalColumnNewWidth;
    }
    if (
      dragState.nextColumnInfo &&
      colIndex === dragState.nextColumnInfo.index &&
      finalNextColumnNewWidth !== undefined
    ) {
      return colIndex > 0 && spacing > 0
        ? finalNextColumnNewWidth - spacing
        : finalNextColumnNewWidth;
    }
    return baseWidth || 100;
  });
};

function setColumnWidth({
  table,
  map,
  start,
  colIndex,
  width,
  tr,
}: {
  table: ProseMirrorNode;
  map: TableMap;
  start: number;
  colIndex: number;
  width: number;
  tr: Transaction;
}): void {
  for (let row = 0; row < map.height; row++) {
    const pos = map.map[row * map.width + colIndex];
    const placement = map.findCell(pos);
    if (placement.row < row) {
      continue;
    }
    const cell = table.nodeAt(pos);
    if (!cell) {
      continue;
    }
    const attrs = cell.attrs;
    const colwidth = Array.isArray(attrs.colwidth)
      ? attrs.colwidth.slice()
      : Array(placement.colspan).fill(0);
    while (colwidth.length < placement.colspan) {
      colwidth.push(0);
    }

    const colIndexInCell = colIndex - placement.col;
    if (colIndexInCell >= 0 && colIndexInCell < placement.colspan) {
      colwidth[colIndexInCell] = width;
      tr.setNodeAttribute(start + pos, 'colwidth', colwidth);
    }
  }
}
